import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ThreadResourceManager {
    private Map<String, Thread> threadMap;
    private ScheduledExecutorService scheduler;

    public ThreadResourceManager() {
        // Using ConcurrentHashMap for thread safety
        this.threadMap = new ConcurrentHashMap<>();

        // Initialize the scheduled executor service
        this.scheduler = Executors.newSingleThreadScheduledExecutor();

        // Start the monitoring task that runs every second
        scheduler.scheduleAtFixedRate(this::cleanupDeadThreads, 1, 1, TimeUnit.SECONDS);
    }

    public boolean createDaemonThread(String threadName, Runnable task) {
        // Check for null parameters
        if (threadName == null || task == null) {
            return false;
        }

        // Create a new thread with the given name and task
        Thread thread = new Thread(task, threadName);

        // Set the thread as a daemon thread
        thread.setDaemon(true);

        // Start the thread
        thread.start();

        // Store the thread in the internal map
        threadMap.put(threadName, thread);

        return true;
    }

    public boolean stopDaemonThread(String threadName) {
        // Check for null parameter
        if (threadName == null) {
            return false;
        }

        // Get the thread from the map
        Thread thread = threadMap.get(threadName);

        // If thread not found, return false
        if (thread == null) {
            return false;
        }

        // Interrupt the thread
        thread.interrupt();

        // Remove the thread from the map
        threadMap.remove(threadName);

        return true;
    }

    public int getActiveThreadCount() {
        return threadMap.size();
    }

    private void cleanupDeadThreads() {
        // Remove any threads that are no longer alive
        threadMap.entrySet().removeIf(entry -> !entry.getValue().isAlive());
    }

    // Optional: Method to get a thread by name
    public Thread getThread(String threadName) {
        return threadMap.get(threadName);
    }

    // Optional: Method to get all threads
    public Map<String, Thread> getAllThreads() {
        return new ConcurrentHashMap<>(threadMap);
    }
}

