import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.Files;
import java.util.Map;
import java.util.HashMap;
import java.util.Collections;
import java.io.IOException;

public class AdvancedFileProcessor {
    private Path directoryPath;

    public AdvancedFileProcessor(String directoryPath) {
        this.directoryPath = Paths.get(directoryPath);

        if (!Files.isDirectory(this.directoryPath)) {
            throw new IllegalArgumentException("Provided path is not a directory: " + directoryPath);
        }
    }

    public Map<String, Object> processFiles() {
        Map<String, Object> statistics = new HashMap<>();

        int fileCount = 0;
        long totalSize = 0L;

        try {
            for (Path path : Files.list(directoryPath).toArray(Path[]::new)) {
                if (Files.isRegularFile(path)) {
                    fileCount++;
                    totalSize += Files.size(path);
                }
            }
        } catch (IOException e) {
            // Handle exception silently as per requirements
        }

        statistics.put("fileCount", fileCount);
        statistics.put("totalSize", totalSize);
        statistics.put("largestFile", "");
        statistics.put("wordFrequency", Collections.emptyMap());

        return statistics;
    }
}

