public class LinkedList<D> {
    private Node<D> head;
    private Node<D> tail;
    private int size;

    public LinkedList() {
        this.head = null;
        this.tail = null;
        this.size = 0;
    }

    public void add(D data) {
        Node<D> newNode = new Node<>(data);

        if (head == null) {
            // List is empty
            head = newNode;
            tail = newNode;
        } else {
            // List is not empty
            newNode.setPrev(tail);
            tail.setNext(newNode);
            tail = newNode;
        }

        size++;
    }

    public int size() {
        return size;
    }

    // Inner Node class for the doubly linked list
    private static class Node<D> {
        private D data;
        private Node<D> next;
