import java.util.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.Optional;
import java.util.stream.Collectors;

public class UserManager {
    private List<User> users;
    private AtomicLong nextId;

    public UserManager() {
        this.users = new ArrayList<>();
        this.nextId = new AtomicLong(1);
    }

    public User createUser(String username, String email, String password) {
        // Validate inputs
        if (username == null) {
            throw new IllegalArgumentException("Username cannot be null");
        }
        if (email == null) {
            throw new IllegalArgumentException("Email cannot be null");
        }
        if (password == null) {
            throw new IllegalArgumentException("Password cannot be null");
        }

        // Check if username or email already exists (including inactive users)
        if (isUsernameTaken(username)) {
            throw new IllegalArgumentException("Username already exists: " + username);
        }
        if (isEmailTaken(email)) {
            throw new IllegalArgumentException("Email already exists: " + email);
        }

        User user = new User(nextId.getAndIncrement(), username, email, password);
        users.add(user);
        return user;
    }

    public Optional<User> findUserById(Long id) {
        return users.stream()
                   .filter(user -> user.getId().equals(id))
                   .findFirst();
    }

    public List<User> getAllActiveUsers() {
        return users.stream()
                   .filter(User::isActive)
                   .collect(Collectors.toList());
    }

    public boolean deactivateUser(Long id) {
        Optional<User> userOptional = findUserById(id);
        if (userOptional.isPresent()) {
            userOptional.get().setActive(false);
            return true;
        }
        return false;
    }

    public void updateUser(Long id, String username, String email, String password) {
        User user = findUserById(id)
                   .orElseThrow(() -> new IllegalArgumentException("User not found with id: " + id));

        // Check username uniqueness if it's being updated (check against all users including inactive)
        if (username != null && !username.equals(user.getUsername())) {
            if (isUsernameTaken(username)) {
                throw new IllegalArgumentException("Username already exists: " + username);
            }
            user.setUsername(username);
        }

        // Check email uniqueness if it's being updated (check against all users including inactive)
        if (email != null && !email.equals(user.getEmail())) {
            if (isEmailTaken(email)) {
                throw new IllegalArgumentException("Email already exists: " + email);
            }
            user.setEmail(email);
        }

        // Update password if provided
        if (password != null) {
            user.setPassword(password);
        }
    }

    private boolean isUsernameTaken(String username) {
        return users.stream()
                   .anyMatch(u -> u.getUsername().equals(username));
    }

    private boolean isEmailTaken(String email) {
        return users.stream()
                   .anyMatch(u -> u.getEmail().equals(email));
    }

    public List<User> getAllUsers() {
        return new ArrayList<>(users);
    }

    public class User {
