class Fragment {
    private String tag;
    private String content;

    public Fragment(String tag, String content) {
        this.tag = tag;
        this.content = content;
    }

    public String getTag() {
        return tag;
    }

    public String getContent() {
        return content;
    }

    @Override
    public String toString() {
        return "Fragment{tag='" + tag + "', content='" + content + "'}";
    }
}

public class FragmentManager {
    private Map<String, Fragment> fragments;
    private Fragment currentFragment;

    public FragmentManager() {
        this.fragments = new HashMap<>();
        this.currentFragment = null;
    }

    /**
     * Adds a fragment with the specified tag
     * @param tag the tag to associate with the fragment
     * @param fragment the fragment to add
     */
    public void addFragment(String tag, Fragment fragment) {
        fragments.put(tag, fragment);
    }

    /**
     * Switches to the fragment with the specified tag
     * @param tag the tag of the fragment to switch to
     * @return true if the switch was successful, false if the fragment doesn't exist
     */
    public boolean switchFragment(String tag) {
        Fragment fragment = fragments.get(tag);
        if (fragment != null) {
            currentFragment = fragment;
            return true;
        }
        return false;
    }

    /**
     * Retrieves the current fragment
     * @return the current fragment, or null if no fragment is currently selected
     */
    public Fragment getCurrentFragment() {
        return currentFragment;
    }

    /**
     * Gets a fragment by its tag
     * @param tag the tag of the fragment to retrieve
     * @return the fragment with the specified tag, or null if it doesn't exist
     */
    public Fragment getFragment(String tag) {
        return fragments.get(tag);
    }

    /**
     * Removes a fragment by its tag
     * @param tag the tag of the fragment to remove
     * @return the removed fragment, or null if it doesn't exist
     */
    public Fragment removeFragment(String tag) {
        Fragment removed = fragments.remove(tag);
        if (removed != null && currentFragment != null && currentFragment.getTag().equals(tag)) {
            currentFragment = null;
        }
        return removed;
    }

    /**
     * Checks if a fragment with the specified tag exists
     * @param tag the tag to check
     * @return true if a fragment with the tag exists, false otherwise
     */
    public boolean containsFragment(String tag) {
        return fragments.containsKey(tag);
    }

    /**
     * Gets the number of fragments stored
     * @return the number of fragments
     */
    public int getFragmentCount() {
        return fragments.size();
    }
}

