        variables = new HashSet<>();
        implicationGraph = new HashMap<>();
        reverseGraph = new HashMap<>();
    }

    public void addClause(int a, int b) {
        // Add the variables (absolute values) to our set
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));

        // Add implication edges: -a → b and -b → a
        addImplication(-a, b);
        addImplication(-b, a);

        // Add reverse edges: b → -a and a → -b
        addReverseImplication(b, -a);
        addReverseImplication(a, -b);
    }

    private void addImplication(int from, int to) {
        implicationGraph.computeIfAbsent(from, k -> new HashSet<>()).add(to);
    }

    private void addReverseImplication(int from, int to) {
        reverseGraph.computeIfAbsent(from, k -> new HashSet<>()).add(to);
    }

    public boolean isSatisfiable() {
        // First pass of Kosaraju's algorithm
        visited = new HashSet<>();
        finishingTimes = new HashMap<>();
        time = 0;

        // Get all nodes that appear in the graph
        Set<Integer> allNodes = new HashSet<>();
        for (int var : variables) {
            allNodes.add(var);
            allNodes.add(-var);
        }

        // Add any additional nodes that might be in the graph but not in variables
        for (int node : implicationGraph.keySet()) {
            allNodes.add(node);
        }
        for (int node : reverseGraph.keySet()) {
            allNodes.add(node);
        }

        // Perform DFS on reverse graph to compute finishing times
        for (int node : allNodes) {
            if (!visited.contains(node)) {
                dfsReverse(node);
            }
        }

        return true; // Default implementation
    }

    private void dfsReverse(int node) {
        visited.add(node);

        // Visit all neighbors in the reverse graph
        Set<Integer> neighbors = reverseGraph.getOrDefault(node, new HashSet<>());
        for (int neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                dfsReverse(neighbor);
            }
        }

        // Record finishing time
        time++;
        finishingTimes.put(node, time);
    }

    // Helper method to get the variables (for testing purposes)
    public Set<Integer> getVariables() {
        return new HashSet<>(variables);
    }

    // Helper method to get implication edges (for testing purposes)
