import java.util.*;

class TwoSatSolver {
    private Set<Integer> variables;
    private Map<Integer, Set<Integer>> implicationGraph;
    private Map<Integer, Set<Integer>> reverseGraph;
    private Map<Integer, Integer> finishingTimes;
    private Map<Integer, Integer> leaders;
    private Set<Integer> visited;
    private int time;
    private int leader;

    public TwoSatSolver() {
        variables = new HashSet<>();
        implicationGraph = new HashMap<>();
        reverseGraph = new HashMap<>();
    }

    public void addClause(int a, int b) {
        // Add the variables (absolute values) to our set
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));

        // Add implication edges: -a → b and -b → a
        addImplication(-a, b);
        addImplication(-b, a);

        // Add reverse edges: b → -a and a → -b
        addReverseImplication(b, -a);
        addReverseImplication(a, -b);
    }

    private void addImplication(int from, int to) {
        implicationGraph.computeIfAbsent(from, k -> new HashSet<>()).add(to);
    }

    private void addReverseImplication(int from, int to) {
        reverseGraph.computeIfAbsent(from, k -> new HashSet<>()).add(to);
    }

    public boolean isSatisfiable() {
        // First pass of Kosaraju's algorithm
        visited = new HashSet<>();
        finishingTimes = new HashMap<>();
        time = 0;

        // Get all nodes that appear in the graph
        Set<Integer> allNodes = new HashSet<>();
        for (int var : variables) {
            allNodes.add(var);
            allNodes.add(-var);
        }

        // Add any additional nodes that might be in the graph but not in variables
        for (int node : implicationGraph.keySet()) {
            allNodes.add(node);
        }
        for (int node : reverseGraph.keySet()) {
            allNodes.add(node);
        }

        // Perform DFS on reverse graph to compute finishing times
        for (int node : allNodes) {
            if (!visited.contains(node)) {
                dfsReverse(node);
            }
        }

        // Second pass of Kosaraju's algorithm
        visited = new HashSet<>();
        leaders = new HashMap<>();

        // Create a list of nodes sorted by decreasing finishing times
        List<Map.Entry<Integer, Integer>> sortedEntries = new ArrayList<>(finishingTimes.entrySet());
        sortedEntries.sort((a, b) -> b.getValue().compareTo(a.getValue()));

        // Process nodes in decreasing order of finishing times
        for (Map.Entry<Integer, Integer> entry : sortedEntries) {
            int node = entry.getKey();
            if (!visited.contains(node)) {
                leader = node;
                dfsForward(node);
            }
        }

        // Check if any variable and its negation are in the same SCC
        for (int var : variables) {
            if (leaders.getOrDefault(var, 0).equals(leaders.getOrDefault(-var, 0))) {
                return false;
            }
        }

        return true;
    }

    private void dfsReverse(int node) {
        visited.add(node);

        // Visit all neighbors in the reverse graph
        Set<Integer> neighbors = reverseGraph.getOrDefault(node, new HashSet<>());
        for (int neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                dfsReverse(neighbor);
            }
        }

        // Record finishing time
        time++;
        finishingTimes.put(node, time);
    }

    private void dfsForward(int node) {
        visited.add(node);
        leaders.put(node, leader);

        // Visit all neighbors in the original graph
        Set<Integer> neighbors = implicationGraph.getOrDefault(node, new HashSet<>());
        for (int neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                dfsForward(neighbor);
            }
        }
    }

    // Helper method to get the variables (for testing purposes)
    public Set<Integer> getVariables() {
        return new HashSet<>(variables);
    }

    // Helper method to get implication edges (for testing purposes)
    public Map<Integer, Set<Integer>> getImplicationGraph() {
        return new HashMap<>(implicationGraph);
    }

    // Helper method to get finishing times (for testing purposes)
    public Map<Integer, Integer> getFinishingTimes() {
        return new HashMap<>(finishingTimes);
    }

    // Helper method to get leaders (for testing purposes)
    public Map<Integer, Integer> getLeaders() {
        return new HashMap<>(leaders);
    }
}

