            while (queue.isEmpty()) {
                if (nanos <= 0) {
                    return null;
                }
                nanos = notEmpty.awaitNanos(nanos);
            }
            T element = queue.remove();
            totalRemoved++;
            notFull.signal();
            return element;
        } finally {
            lock.unlock();
        }
