import java.util.*;

public class AdditionChainFinder {
    private int minLength;
    private List<Integer> bestChain;

    public List<Integer> findShortestAdditionChain(int target) {
        if (target < 1) {
            throw new IllegalArgumentException("Target number must be at least 1, but was: " + target);
        }

        if (target == 1) {
            return Arrays.asList(1);
        }

        // Initialize for new search
        minLength = Integer.MAX_VALUE;
        bestChain = null;

        // Start DFS with initial chain [1]
        List<Integer> initialChain = new ArrayList<>();
        initialChain.add(1);
        Set<Integer> currentSet = new HashSet<>();
        currentSet.add(1);

        dfs(initialChain, currentSet, target);

        return bestChain != null ? new ArrayList<>(bestChain) : new ArrayList<>();
    }

    private void dfs(List<Integer> chain, Set<Integer> available, int target) {
        int last = chain.get(chain.size() - 1);

        // Pruning: if current chain is already longer than best found, stop
        if (chain.size() >= minLength) {
            return;
        }

        // If we've reached the target
        if (last == target) {
            if (chain.size() < minLength) {
                minLength = chain.size();
                bestChain = new ArrayList<>(chain);
            } else if (chain.size() == minLength) {
                // If same length, check for lexicographically smaller chain
                if (isLexicographicallySmaller(chain, bestChain)) {
                    bestChain = new ArrayList<>(chain);
                }
            }
            return;
        }

        // If we've exceeded the target, no point continuing
        if (last > target) {
            return;
        }

        // Try all pairs of available numbers (including using the same number twice)
        List<Integer> availableList = new ArrayList<>(available);
        Collections.sort(availableList, Collections.reverseOrder()); // Try larger numbers first for efficiency

        for (int i = 0; i < availableList.size(); i++) {
            for (int j = i; j < availableList.size(); j++) {
                int a = availableList.get(i);
                int b = availableList.get(j);
                int sum = a + b;

                // Skip if sum exceeds target or is already in the chain
                if (sum > target || available.contains(sum)) {
                    continue;
                }

                // Add sum to chain and continue DFS
                chain.add(sum);
                available.add(sum);
                dfs(chain, available, target);
                chain.remove(chain.size() - 1);
                available.remove(sum);
            }
        }
    }

    private boolean isLexicographicallySmaller(List<Integer> chain1, List<Integer> chain2) {
        if (chain2 == null) return true;

        for (int i = 0; i < Math.min(chain1.size(), chain2.size()); i++) {
            if (chain1.get(i) < chain2.get(i)) {
                return true;
            } else if (chain1.get(i) > chain2.get(i)) {
                return false;
            }
        }
        return chain1.size() < chain2.size();
    }
}

