            titleCaseString = new StringBuilder(titleCaseString).reverse().toString();
        }

        // Apply length-based markers
        if (titleCaseString.isEmpty()) {
            return "Empty";
        } else if (titleCaseString.length() < 3) {
            return "Short_" + titleCaseString;
        } else if (titleCaseString.length() >= 3 && titleCaseString.length() <= 5) {
            return titleCaseString + "_Medium";
        } else {
            return "Long_" + titleCaseString + "_Processed";
        }
    }
