import java.util.HashMap;
import java.util.Map;

class FileUploadUtil {

    public static String getFilename(String contentDisposition) {
        if (contentDisposition == null || contentDisposition.isEmpty()) {
            return null;
        }

        // First try to find filename* (extended parameter) as it has priority
        String filename = extractFilename(contentDisposition, "filename*=");
        if (filename != null && !filename.isEmpty()) {
            // Handle filename* according to RFC 5987 (simplified)
            // Format: filename*=UTF-8''filename.txt or filename*=utf-8'en'filename.txt
            int firstSingleQuote = filename.indexOf('\'');
            if (firstSingleQuote != -1) {
                int secondSingleQuote = filename.indexOf('\'', firstSingleQuote + 1);
                if (secondSingleQuote != -1) {
                    // Return the actual filename part after the second single quote
                    return filename.substring(secondSingleQuote + 1);
                }
            }
            return filename;
        }

        // If filename* not found or empty, try filename
        filename = extractFilename(contentDisposition, "filename=");
        return filename;
    }

    private static String extractFilename(String contentDisposition, String parameter) {
        int index = contentDisposition.indexOf(parameter);
        if (index == -1) {
            return null;
        }

        int startIndex = index + parameter.length();
        String remainder = contentDisposition.substring(startIndex);

        if (remainder.startsWith("\"")) {
            // Handle double-quoted value
            int endIndex = remainder.indexOf("\"", 1);
            if (endIndex != -1) {
                return remainder.substring(1, endIndex);
            }
        } else if (remainder.startsWith("'")) {
            // Handle single-quoted value
            int endIndex = remainder.indexOf("'", 1);
            if (endIndex != -1) {
                return remainder.substring(1, endIndex);
            }
        } else {
            // Handle unquoted value - read until semicolon or end of string
