    public static Map<String, Object> analyzeGraph(int[][] graph, int source) {
        int n = graph.length;
        int[] distances = new int[n];
        int[] predecessor = new int[n];
        boolean[] visited = new boolean[n];
        int visitedCount = 0;

        // Initialize distances with infinity except for source
        Arrays.fill(distances, Integer.MAX_VALUE);
        Arrays.fill(predecessor, -1);
        distances[source] = 0;

        // Priority queue to process vertices by minimum distance
        PriorityQueue<Vertex> pq = new PriorityQueue<>((v1, v2) -> Integer.compare(v1.distance, v2.distance));
        pq.offer(new Vertex(source, 0));

        while (!pq.isEmpty()) {
            Vertex current = pq.poll();
            int u = current.index;

            // Skip if already processed
            if (visited[u]) continue;
            visited[u] = true;
            visitedCount++; // Increment counter when vertex is processed

            // Update distances for all neighbors
            for (int v = 0; v < n; v++) {
                // Check if there's an edge and vertex is not visited
                if (graph[u][v] != 0 && !visited[v]) {
