public class EnhancedQueue<E> {
    // Nested Node class to represent elements in the queue
    private class Node {
        E data;
        Node next;

        Node(E data) {
            this.data = data;
            this.next = null;
        }
    }

    private Node front;
    private Node rear;
    private int size;

    // Default constructor
    public EnhancedQueue() {
        this.front = null;
        this.rear = null;
        this.size = 0;
    }

    // Add element to the end of the queue
    public void enqueue(E newData) {
        Node newNode = new Node(newData);

        if (isEmpty()) {
            front = rear = newNode;
        } else {
            rear.next = newNode;
            rear = newNode;
        }
        size++;
    }

    // Remove and return the front element
    public E dequeue() {
        if (isEmpty()) {
            throw new RuntimeException("Queue is empty");
        }

        E data = front.data;
        front = front.next;

        // If queue becomes empty after dequeue
        if (front == null) {
            rear = null;
        }

        size--;
        return data;
    }

    // View the front element without removing it
    public E peek() {
        if (isEmpty()) {
            throw new RuntimeException("Queue is empty");
        }
        return front.data;
    }

    // Check if the queue is empty
    public boolean isEmpty() {
        return front == null;
    }

    // Return the number of elements in the queue
    public int size() {
        return size;
    }
}

