public class EnhancedQueue<E> {
    private static final int DEFAULT_CAPACITY = 10;

    // Nested Node class to represent elements in the queue
    private class Node {
        E data;
        Node next;

        Node(E data) {
            this.data = data;
            this.next = null;
        }
    }

    private Node front;
    private Node rear;
    private int size;
    private int capacity;

    // Default constructor
    public EnhancedQueue() {
        this.front = null;
        this.rear = null;
        this.size = 0;
        this.capacity = DEFAULT_CAPACITY;
    }

    // Constructor with capacity parameter
    public EnhancedQueue(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("Capacity must be greater than zero");
        }
        this.front = null;
        this.rear = null;
        this.size = 0;
        this.capacity = capacity;
    }

    // Add element to the end of the queue
    public void enqueue(E newData) {
        if (size >= capacity) {
            throw new IllegalStateException("Queue is full");
        }

        Node newNode = new Node(newData);

        if (isEmpty()) {
            front = rear = newNode;
        } else {
            rear.next = newNode;
            rear = newNode;
        }
        size++;
    }

    // Remove and return the front element
    public E dequeue() {
        if (isEmpty()) {
            throw new RuntimeException("Queue is empty");
        }

        E data = front.data;
        front = front.next;

        // If queue becomes empty after dequeue
        if (front == null) {
            rear = null;
        }

        size--;
        return data;
    }

    // View the front element without removing it
    public E peek() {
        if (isEmpty()) {
            throw new RuntimeException("Queue is empty");
        }
        return front.data;
    }

    // Check if the queue is empty
    public boolean isEmpty() {
        return front == null;
    }

    // Check if the queue is full
    public boolean isFull() {
        return size == capacity;
    }

    // Return the number of elements in the queue
    public int size() {
        return size;
    }

    // Return the capacity of the queue
    public int capacity() {
        return capacity;
    }

    // Remove all elements from the queue and reset its state
    public void clear() {
        front = null;
        rear = null;
        size = 0;
    }

    // Check if the specified element exists in the queue
    public boolean contains(E element) {
        Node current = front;
        while (current != null) {
            if (element == null ? current.data == null : element.equals(current.data)) {
                return true;
            }
            current = current.next;
        }
        return false;
    }

    // Print all elements in the queue in order
    public void printQueue() {
        if (isEmpty()) {
            System.out.println("Queue is empty");
            return;
        }

        Node current = front;
        while (current != null) {
            System.out.print(current.data);
            if (current.next != null) {
                System.out.print(" ");
            }
            current = current.next;
        }
        System.out.println();
    }
}
