            if (index < 0 || index >= record.length) {
                return false;
            }
        }
        return true;
    }

    private String createExactKey(String[] record, int[] keyIndices) {
        StringBuilder keyBuilder = new StringBuilder();
        for (int index : keyIndices) {
            keyBuilder.append(trimValue(record[index])).append("|");
        }
        return keyBuilder.toString();
    }

    private String[] createContainsKeys(String[] record, int[] keyIndices, boolean caseInsensitive) {
        String[] keys = new String[2];
        for (int i = 0; i < 2; i++) {
            int index = keyIndices[i];
            String value = trimValue(record[index]);
            keys[i] = caseInsensitive ? value.toLowerCase() : value;
        }
        return keys;
    }

    private boolean keysMatch(String[] keys1, String[] keys2) {
        // Check if keys1 contains keys2 or keys2 contains keys1 for both key positions
        return (keys1[0].contains(keys2[0]) || keys2[0].contains(keys1[0])) &&
               (keys1[1].contains(keys2[1]) || keys2[1].contains(keys1[1]));
    }

    private String trimValue(String value) {
        return value != null ? value.trim() : "";
    }

    private String[] combineRecords(String[] record1, String[] record2) {
        String[] combined = new String[record1.length + record2.length];
        System.arraycopy(record1, 0, combined, 0, record1.length);
        System.arraycopy(record2, 0, combined, record1.length, record2.length);
        return combined;
    }

    private int getMaxRecordLength(List<String[]> dataset) {
        int maxLength = 0;
        for (String[] record : dataset) {
            maxLength = Math.max(maxLength, record.length);
        }
        return maxLength;
    }

    private void padUnmatchedRecords(List<String[]> unmatchedRecords, int targetLength) {
        for (int i = 0; i < unmatchedRecords.size(); i++) {
            String[] record = unmatchedRecords.get(i);
            if (record.length < targetLength) {
                String[] paddedRecord = new String[targetLength];
                System.arraycopy(record, 0, paddedRecord, 0, record.length);
                for (int j = record.length; j < targetLength; j++) {
                    paddedRecord[j] = "";
                }
                unmatchedRecords.set(i, paddedRecord);
            }
        }
    }
}
