import java.util.ArrayList;
import java.util.List;

class SubsetGenerator {
    public List<List<Integer>> generateSubsets(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();

        // Add empty subset
        result.add(new ArrayList<>());

        // For each element in the array
        for (int i = 0; i < nums.length; i++) {
            // Create new subsets by appending current element to every previously generated subset
            int currentSize = result.size();
            for (int j = 0; j < currentSize; j++) {
                List<Integer> existingSubset = result.get(j);
                // Only add subsets of size up to 2
                if (existingSubset.size() < 2) {
                    List<Integer> newSubset = new ArrayList<>(existingSubset);
                    newSubset.add(nums[i]);
                    result.add(newSubset);
                }
            }
        }

        return result;
    }
}

