        // Check if nodes exist
        if (!adjacencyList.containsKey(start)) {
            throw new IllegalArgumentException("Start node does not exist in the graph");
        }
        if (!adjacencyList.containsKey(end)) {
            throw new IllegalArgumentException("End node does not exist in the graph");
        }

        // If start and end are the same, return a list with just that node
        if (start.equals(end)) {
            List<String> path = new ArrayList<>();
            path.add(start);
            return path;
        }

        // Initialize data structures for Dijkstra's algorithm
        Map<String, Integer> distances = new HashMap<>();
        Map<String, String> previous = new HashMap<>();
        Set<String> visited = new HashSet<>();
        PriorityQueue<NodeDistance> pq = new PriorityQueue<>((a, b) -> Integer.compare(a.distance, b.distance));

        // Initialize distances
        for (String node : adjacencyList.keySet()) {
            distances.put(node, Integer.MAX_VALUE);
        }
        distances.put(start, 0);
        pq.offer(new NodeDistance(start, 0));

        // Dijkstra's algorithm
        while (!pq.isEmpty()) {
            NodeDistance current = pq.poll();
            String currentNode = current.node;

            // If we've already processed this node, skip it
            if (visited.contains(currentNode)) {
                continue;
            }

            // Mark as visited
            visited.add(currentNode);

            // If we reached the destination, we can stop
            if (currentNode.equals(end)) {
                break;
            }

            // Check all neighbors
            for (Edge edge : adjacencyList.get(currentNode)) {
                String neighbor = edge.destination;
                int weight = edge.weight;
                int newDistance = distances.get(currentNode) + weight;

                // If we found a shorter path to the neighbor
                if (newDistance < distances.get(neighbor)) {
                    distances.put(neighbor, newDistance);
                    previous.put(neighbor, currentNode);
                    pq.offer(new NodeDistance(neighbor, newDistance));
                }
            }
        }

        // If we never reached the end node, there's no path
        if (distances.get(end) == Integer.MAX_VALUE) {
            return new ArrayList<>(); // Return empty list
        }

        // Reconstruct the path
        List<String> path = new ArrayList<>();
        String current = end;
        while (current != null) {
            path.add(current);
            current = previous.get(current);
        }

        // Reverse the path to get it from start to end
        Collections.reverse(path);
        return path;
    }

    // Helper class for Dijkstra's algorithm
    private static class NodeDistance {
        String node;
        int distance;

        NodeDistance(String node, int distance) {
            this.node = node;
            this.distance = distance;
        }
    }

    static class Edge {
        String destination;
        int weight;

        public Edge(String destination, int weight) {
            this.destination = destination;
            this.weight = weight;
        }
    }
}
