            for (char c : input.toCharArray()) {
                // Only process bracket characters
                if (openingBrackets.contains(c)) {
                    stack.push(c);
                } else if (closingBrackets.contains(c)) {
                    // If stack is empty or brackets don't match
                    if (stack.isEmpty() || stack.pop() != bracketPairs.get(c)) {
                        result.put("balanced", false);
                        return result;
                    }
                }
            }
        }

        // Balanced if stack is empty (all brackets matched)
        result.put("balanced", stack.isEmpty());
        return result;
    }
}

