import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.Objects;

class PollingQueue<T> {
    private final Queue<T> queue;
    private final AtomicInteger pollingCount;
    private final int maxPollingAttempts;

    public PollingQueue(int maxPollingAttempts) {
        this.queue = new LinkedList<>();
        this.pollingCount = new AtomicInteger(0);
        this.maxPollingAttempts = maxPollingAttempts;
    }

    public synchronized void enqueue(T element) {
        queue.add(element);
        this.notify();
    }

    public synchronized T poll() {
        if (pollingCount.get() >= maxPollingAttempts) {
            throw new IllegalStateException("Maximum polling attempts exceeded: " + maxPollingAttempts);
        }

        T element = queue.poll();
        if (element != null) {
            pollingCount.incrementAndGet();
        }
        return element;
    }

    public synchronized T waitForElement(long timeoutMillis) throws InterruptedException {
        long startTime = System.currentTimeMillis();
        long remainingTime = timeoutMillis;

        while (queue.isEmpty() && remainingTime > 0) {
            this.wait(remainingTime);
            remainingTime = timeoutMillis - (System.currentTimeMillis() - startTime);
        }

        return queue.poll();
    }

    public synchronized void resetPollingCount() {
        pollingCount.set(0);
    }

    public int getPollingCount() {
        return pollingCount.get();
    }

    public int getMaxPollingAttempts() {
        return maxPollingAttempts;
    }

    public synchronized Queue<T> getQueue() {
        return new LinkedList<>(queue);
    }

    @Override
    public synchronized boolean equals(Object obj) {
        if (this == obj) {
            return true;
        }
        if (obj == null || getClass() != obj.getClass()) {
            return false;
        }
        PollingQueue<?> that = (PollingQueue<?>) obj;
        return maxPollingAttempts == that.maxPollingAttempts &&
               pollingCount.get() == that.pollingCount.get() &&
               Objects.equals(queue, that.queue);
    }

    @Override
    public synchronized int hashCode() {
        return Objects.hash(queue, pollingCount.get(), maxPollingAttempts);
    }
}
