import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

class AsyncOperationManager {

    public <T> CompletableFuture<T> executeWithTimeoutAndRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries) {
        return retryTask(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries, 0);
    }

    private <T> CompletableFuture<T> retryTask(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries,
            int currentAttempt) {

        return CompletableFuture.supplyAsync(taskSupplier)
                .orTimeout(timeout, timeUnit)
                .handle((result, throwable) -> {
                    if (throwable == null) {
                        return result;
                    } else if (currentAttempt < maxRetries) {
                        try {
                            Thread.sleep(500);
                        } catch (InterruptedException e) {
                            throw new CompletionException(e);
                        }
                        return null; // Signal that we need to retry
                    } else {
                        return fallbackValue;
                    }
                })
                .thenCompose(result -> {
                    if (result == null) {
                        // Need to retry
                        return retryTask(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries, currentAttempt + 1);
                    } else {
                        return CompletableFuture.completedFuture(result);
                    }
                });
    }
}

