import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

class AsyncOperationManager {

    public <T> CompletableFuture<T> executeWithTimeoutAndRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries) {
        return retryTask(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries, 0, null);
    }

    private <T> CompletableFuture<T> retryTask(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries,
            int currentAttempt,
            Throwable lastException) {

        return CompletableFuture.supplyAsync(taskSupplier)
                .orTimeout(timeout, timeUnit)
                .handle((result, throwable) -> {
                    if (throwable == null) {
                        return CompletableFuture.completedFuture(result);
                    } else {
                        Throwable cause = throwable instanceof CompletionException ? throwable.getCause() : throwable;
                        if (currentAttempt < maxRetries) {
                            // Schedule retry with delay
                            return CompletableFuture.runAsync(() -> {
                                try {
                                    Thread.sleep(500);
                                } catch (InterruptedException e) {
                                    throw new CompletionException(e);
                                }
                            }).thenCompose(v -> retryTask(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries, currentAttempt + 1, cause));
                        } else {
                            // Last attempt failed
                            if (isTimeoutException(cause)) {
                                return CompletableFuture.completedFuture(fallbackValue);
                            } else {
                                return CompletableFuture.<T>failedFuture(cause);
                            }
                        }
                    }
                })
                .thenCompose(future -> future);
    }

    private boolean isTimeoutException(Throwable throwable) {
        return throwable instanceof java.util.concurrent.TimeoutException;
    }
}

