    private void initializeGameState() {
        gameState.put("gameStarted", false);
        gameState.put("gamePaused", false);
        gameState.put("gameOver", false);
    }

    public void startNewGame(int startX, int startY) {
        player.setPosition(startX, startY);
        gameState.put("gameStarted", true);
        gameState.put("gamePaused", false);
        gameState.put("gameOver", false);
        this.score = 0;
    }

    public Player getPlayer() {
        return player;
    }

    public int[] handlePlayerMovement(String direction) {
        // Check if game is started and not paused
        if (!gameState.get("gameStarted") || gameState.get("gamePaused")) {
            return player.getPosition();
        }

        switch (direction.toUpperCase()) {
            case "UP":
                player.move(0, -1);
                break;
            case "DOWN":
                player.move(0, 1);
                break;
            case "LEFT":
                player.move(-1, 0);
                break;
            case "RIGHT":
                player.move(1, 0);
                break;
            default:
                throw new IllegalArgumentException("Invalid direction: " + direction);
        }
        return player.getPosition();
    }

    public boolean handleMouseClick(int clickX, int clickY) {
        if (gameState.get("gameStarted")) {
            int[] playerPosition = player.getPosition();
            int playerX = playerPosition[0];
            int playerY = playerPosition[1];

            // Calculate distance between click and player
            double distance = Math.sqrt(Math.pow(clickX - playerX, 2) + Math.pow(clickY - playerY, 2));

            if (distance <= 50) {
                score += 10;
                return true;
            }
        }
        return false;
    }

    public Map<String, Boolean> getGameState() {
        // Return a copy of the map to prevent external modification
        return new HashMap<>(gameState);
    }

    public int getScore() {
        return score;
    }

    // Additional methods to control game state
    public void pauseGame() {
        if (gameState.get("gameStarted") && !gameState.get("gameOver")) {
            gameState.put("gamePaused", true);
        }
    }

    public void resumeGame() {
        if (gameState.get("gameStarted") && gameState.get("gamePaused") && !gameState.get("gameOver")) {
            gameState.put("gamePaused", false);
        }
    }

    public void endGame() {
        gameState.put("gameOver", true);
    }
}

