public class Venue {
    private int rows;
    private int columns;
    private boolean[][] seats;

    public Venue(int rows, int columns) {
        this.rows = rows;
        this.columns = columns;
        this.seats = new boolean[rows][columns]; // false means available, true means reserved
    }

    public int getNumberOfSeats() {
        return rows * columns;
    }

    public boolean reserveSeat(int row, int col) {
        // Check if coordinates are valid (1-based indexing)
        if (row < 1 || row > rows || col < 1 || col > columns) {
            throw new IllegalArgumentException("Invalid seat coordinates");
        }

        // Convert to 0-based indexing
        int rowIndex = row - 1;
        int colIndex = col - 1;

        // Check if seat is already reserved
        if (seats[rowIndex][colIndex]) {
            return false; // Already reserved
        }

        // Reserve the seat
        seats[rowIndex][colIndex] = true;
        return true; // Successfully reserved
    }

    public int getAvailableSeats() {
        int availableCount = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                if (!seats[i][j]) {
                    availableCount++;
                }
            }
        }
        return availableCount;
    }

    public int[] getBestAvailableSeat() {
        // Check each row from front to back
        for (int row = 0; row < rows; row++) {
            // Find available seats in this row
            Integer bestCol = getBestAvailableColumnInRow(row);
            if (bestCol != null) {
                // Return 1-based indexing
                return new int[]{row + 1, bestCol + 1};
            }
        }
        return null; // No available seats
    }

    private Integer getBestAvailableColumnInRow(int row) {
        // Start from the center and work outward
        int center = columns / 2;

        // Check center seat first
        if (!seats[row][center]) {
            return center;
        }

        // Check alternating left and right from center
        for (int offset = 1; offset <= columns / 2 + 1; offset++) {
            // Check left side
            int leftCol = center - offset;
            if (leftCol >= 0 && !seats[row][leftCol]) {
                return leftCol;
            }

            // Check right side
            int rightCol = center + offset;
            if (rightCol < columns && !seats[row][rightCol]) {
                return rightCol;
            }
        }

        return null; // No available seats in this row
    }
}

