import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

public class UserAuthenticationService {

    private Map<String, User> userDatabase;
    private MessageDigest sha256Digest;

    public UserAuthenticationService() throws NoSuchAlgorithmException {
        this.userDatabase = new HashMap<>();
        this.sha256Digest = MessageDigest.getInstance("SHA-256");
        initializeTestUsers();
    }

    private String hashPassword(String password) {
        sha256Digest.reset();
        byte[] hashBytes = sha256Digest.digest(password.getBytes());
        return Base64.getEncoder().encodeToString(hashBytes);
    }

    private void initializeTestUsers() {
        String adminEmail = "admin@example.com";
        String adminPassword = "admin123";
        String adminRole = "ADMIN";
        String adminPasswordHash = hashPassword(adminPassword);
        User adminUser = new User(adminEmail, adminPasswordHash, adminRole);
        userDatabase.put(adminEmail, adminUser);

        String userEmail = "user@example.com";
        String userPassword = "user123";
        String userRole = "USER";
        String userPasswordHash = hashPassword(userPassword);
        User regularUser = new User(userEmail, userPasswordHash, userRole);
        userDatabase.put(userEmail, regularUser);
    }

    public Optional<User> authenticate(String email, String password) {
        User user = userDatabase.get(email);
        if (user != null) {
            String hashedPassword = hashPassword(password);
            if (user.getPasswordHash().equals(hashedPassword)) {
                return Optional.of(user);
            }
        }
        return Optional.empty();
    }

    public static class User {
        private String email;
        private String passwordHash;
        private String role;

        public User(String email, String passwordHash, String role) {
            this.email = email;
            this.passwordHash = passwordHash;
            this.role = role;
        }

        public String getEmail() {
            return email;
        }

        public String getPasswordHash() {
            return passwordHash;
