import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;

public class CategoryManager {
    private List<Category> categories;
    private String currentCategory;

    public CategoryManager() {
        categories = new ArrayList<>();
        Category defaultCategory = new Category("生活");
        categories.add(defaultCategory);
        currentCategory = "生活";
    }

    public boolean addCategory(String categoryName) {
        // Check if category already exists
        for (Category category : categories) {
            if (category.getName().equals(categoryName)) {
                return false;
            }
        }

        // Add new category if it doesn't exist
        categories.add(new Category(categoryName));
        return true;
    }

    public List<Note> removeCategory(String categoryName) {
        // Find and remove the category
        Category categoryToRemove = null;
        int indexToRemove = -1;

        for (int i = 0; i < categories.size(); i++) {
            if (categories.get(i).getName().equals(categoryName)) {
                categoryToRemove = categories.get(i);
                indexToRemove = i;
                break;
            }
        }

        // If category doesn't exist, return null
        if (categoryToRemove == null) {
            return null;
        }

        // Remove the category
        categories.remove(indexToRemove);

        // If the removed category was the current one, update current category
        if (currentCategory.equals(categoryName)) {
            if (categories.isEmpty()) {
                currentCategory = "";
            } else {
                currentCategory = categories.get(0).getName();
            }
        }

        // Return the list of notes from the removed category
        return categoryToRemove.getNotes();
    }

    public static class Note {
        private static final AtomicLong idGenerator = new AtomicLong(0);
        private final long id;
        private final String title;
        private final String content;

        public Note(String title, String content) {
            this.id = idGenerator.incrementAndGet();
            this.title = title;
            this.content = content;
        }

        public long getId() {
