import java.util.Date;
import java.util.HashMap;
import java.util.Map;

class AuthTokenValidator {
    private Map<String, TokenInfo> tokenDatabase;
    private Map<String, User> userDatabase;

    public AuthTokenValidator() {
        // Initialize token database with at least one valid token
        tokenDatabase = new HashMap<>();
        // Token with IP 192.168.1.1, expires in 1 hour, status 1, for user1
        tokenDatabase.put("user192.168.1.1", new TokenInfo(new Date(System.currentTimeMillis() + 3600000), 1, "user1"));

        // Initialize user database with one user
        userDatabase = new HashMap<>();
        userDatabase.put("user1", new User("user1", "John Doe", "john@example.com"));
    }

    public Map<String, Object> validateToken(String token, String clientIp) {
        Map<String, Object> result = new HashMap<>();
        if (token == null || token.isEmpty()) {
            result.put("valid", false);
            result.put("message", "Token is empty");
            return result;
        }
        if (!token.contains("user")) {
            result.put("valid", false);
            result.put("message", "Token format invalid");
            return result;
        }

        // Extract IP address from token (everything after 'user')
        int userIndex = token.indexOf("user");
        String tokenIp = token.substring(userIndex + 4); // +4 to skip 'user'

        // Compare with provided client IP
        if (!tokenIp.equals(clientIp)) {
            result.put("valid", false);
            result.put("message", "IP address mismatch");
            return result;
        }

        // Check if token exists in database
        if (!tokenDatabase.containsKey(token)) {
            result.put("valid", false);
            result.put("message", "Token not found");
            return result;
        }

        // Get token info
        TokenInfo tokenInfo = tokenDatabase.get(token);

        // Check token expiration
        if (tokenInfo.getExpirationDate().before(new Date())) {
            result.put("valid", false);
            result.put("message", "Token expired");
            return result;
        }

        // Check token status
        if (tokenInfo.getStatus() != 1) {
            result.put("valid", false);
            result.put("message", "Token invalid");
            return result;
        }

        // Check if user exists
        if (!userDatabase.containsKey(tokenInfo.getUsername())) {
            result.put("valid", false);
            result.put("message", "User not found");
            return result;
        }

        // All checks passed
        result.put("valid", true);
        result.put("message", "Validation successful");
        result.put("user", userDatabase.get(tokenInfo.getUsername()));
        return result;
    }

    // Inner class to hold token information
    private static class TokenInfo {
        private Date expirationDate;
        private int status;
        private String username;

        public TokenInfo(Date expirationDate, int status, String username) {
            this.expirationDate = expirationDate;
            this.status = status;
            this.username = username;
        }

        public Date getExpirationDate() {
            return expirationDate;
        }

        public int getStatus() {
            return status;
        }

        public String getUsername() {
            return username;
        }
    }

    // Inner class to represent a User
    private static class User {
        private String username;
        private String fullName;
        private String email;

        public User(String username, String fullName, String email) {
            this.username = username;
            this.fullName = fullName;
            this.email = email;
        }

        public String getUsername() {
            return username;
        }

        public String getFullName() {
            return fullName;
        }

        public String getEmail() {
            return email;
        }
    }
}

