        // Switch players
        currentPlayer = (currentPlayer == 'X') ? 'O' : 'X';
        return true;
    }

    private boolean checkWin(int row, int col) {
        char player = board[row][col];

        // Check row
        boolean rowWin = true;
        for (int j = 0; j < board[0].length; j++) {
            if (board[row][j] != player) {
                rowWin = false;
                break;
            }
        }
        if (rowWin) return true;

