import java.util.List;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.lang.reflect.Field;

public class PaginationService<T> {

    public static class PaginatedResult<T> {
        private List<T> items;
        private int total;

        public PaginatedResult(List<T> items, int total) {
            this.items = items;
            this.total = total;
        }

        public List<T> getItems() {
            return items;
        }

        public int getTotal() {
            return total;
        }
    }

    public PaginatedResult<T> paginate(List<T> items, int page, int rowsPerPage, String key, String sortBy) {
        if (items == null) {
            items = new ArrayList<>();
        }

        // Filter items if key is provided
        List<T> filteredItems = items;
        if (key != null && !key.trim().isEmpty()) {
            filteredItems = filterItems(items, key);
        }

        // Sort items if sortBy is provided
        List<T> processedItems = filteredItems;
        if (sortBy != null && !sortBy.trim().isEmpty()) {
            processedItems = sortItems(filteredItems, sortBy);
        }

        int total = processedItems.size();

        // Handle edge cases
        if (page < 1 || rowsPerPage <= 0) {
            return new PaginatedResult<>(new ArrayList<>(), total);
        }

        // Calculate start and end indices (0-based)
        int startIndex = (page - 1) * rowsPerPage;
        int endIndex = Math.min(startIndex + rowsPerPage, total);

        // If start index is beyond the list size, return empty list
        if (startIndex >= total) {
            return new PaginatedResult<>(new ArrayList<>(), total);
        }

        // Extract the sublist for the current page
        List<T> pageItems = new ArrayList<>(processedItems.subList(startIndex, endIndex));

        return new PaginatedResult<>(pageItems, total);
    }

    private List<T> filterItems(List<T> items, String key) {
        List<T> filtered = new ArrayList<>();
        String lowerCaseKey = key.toLowerCase();

        for (T item : items) {
            if (item != null && item.toString().toLowerCase().contains(lowerCaseKey)) {
                filtered.add(item);
            }
        }

        return filtered;
    }

    private List<T> sortItems(List<T> items, String sortBy) {
        if (items.isEmpty()) {
            return items;
        }

        boolean descending = false;
        String fieldName = sortBy;

        // Check if sorting is descending
        if (sortBy.startsWith("-")) {
            descending = true;
            fieldName = sortBy.substring(1);
        }

        final String finalFieldName = fieldName;
        final boolean finalDescending = descending;

        try {
            // Create comparator using reflection
            Comparator<T> comparator = (o1, o2) -> {
                try {
                    Field field = o1.getClass().getDeclaredField(finalFieldName);
                    field.setAccessible(true);

                    Object value1 = field.get(o1);
                    Object value2 = field.get(o2);

                    if (value1 == null && value2 == null) return 0;
                    if (value1 == null) return finalDescending ? 1 : -1;
                    if (value2 == null) return finalDescending ? -1 : 1;

                    if (value1 instanceof Comparable && value2 instanceof Comparable) {
                        int comparison = ((Comparable) value1).compareTo((Comparable) value2);
                        return finalDescending ? -comparison : comparison;
                    }

                    // Fallback to string comparison
                    int comparison = value1.toString().compareTo(value2.toString());
                    return finalDescending ? -comparison : comparison;

                } catch (Exception e) {
                    return 0; // If field access fails, treat as equal
                }
            };

            List<T> sortedItems = new ArrayList<>(items);
            Collections.sort(sortedItems, comparator);
            return sortedItems;

        } catch (Exception e) {
            // If reflection fails, return original list
            return items;
        }
    }
}

