import java.util.HashMap;
import java.util.Map;

public class PathAnalyzer {

    public static Map<String, Object> analyzePath(String filePath) {
        if (filePath == null || filePath.isEmpty()) {
            throw new IllegalArgumentException("File path cannot be null or empty");
        }

        Map<String, Object> result = new HashMap<>();

        // Extract filename from the path
        String filename = extractFilename(filePath);
        result.put("filename", filename);

        // Extract extension from the filename
        String extension = extractExtension(filename);
        result.put("extension", extension);

        // Extract parent directory
        String parentDir = extractParentDirectory(filePath);
        result.put("parentDir", parentDir);

        return result;
    }

    private static String extractFilename(String filePath) {
        // Handle both forward slash and backslash separators
        int lastSlashIndex = Math.max(filePath.lastIndexOf('/'), filePath.lastIndexOf('\\'));

        if (lastSlashIndex == -1) {
            // No directory separator found, the entire string is the filename
            return filePath;
        } else {
            // Extract the portion after the last separator
            return filePath.substring(lastSlashIndex + 1);
        }
    }

    private static String extractExtension(String filename) {
        // Find the last dot in the filename
        int lastDotIndex = filename.lastIndexOf('.');

        // If no dot exists, or dot is at the beginning, or dot is at the end, return empty string
        if (lastDotIndex == -1 || lastDotIndex == 0 || lastDotIndex == filename.length() - 1) {
            return "";
        } else {
            // Extract the portion after the last dot
            return filename.substring(lastDotIndex + 1);
        }
    }

    private static String extractParentDirectory(String filePath) {
        // Normalize the path separators to forward slashes
        String normalizedPath = filePath.replace('\\', '/');

        // Remove trailing slashes
        while (normalizedPath.endsWith("/") && normalizedPath.length() > 1) {
            normalizedPath = normalizedPath.substring(0, normalizedPath.length() - 1);
        }

        // Find the last slash
        int lastSlashIndex = normalizedPath.lastIndexOf('/');

        if (lastSlashIndex == -1) {
            // No parent directory
            return "";
        } else if (lastSlashIndex == 0) {
            // Parent is the root directory
            return "/";
        } else {
            // Extract parent directory and normalize
            return normalizePath(normalizedPath.substring(0, lastSlashIndex));
        }
    }

    private static String normalizePath(String path) {
        if (path == null || path.isEmpty()) {
            return "";
        }

        // Convert backslashes to forward slashes
        path = path.replace('\\', '/');

        // Handle root directory
        if (path.equals("/")) {
            return "/";
        }

        // Remove trailing slashes
        while (path.endsWith("/") && path.length() > 1) {
            path = path.substring(0, path.length() - 1);
        }

        return path;
    }
}

