    public MatrixResult processMatrix(int[][] matrix, boolean useSpaceEfficient) {
        // Input validation
        if (matrix == null || matrix.length == 0 || matrix[0].length == 0) {
            throw new IllegalArgumentException("Matrix cannot be null or empty");
        }

        long startTime = System.currentTimeMillis();

        // Create a deep copy of the original matrix
        int[][] originalMatrix = deepCopy(matrix);

        // Count zeros in the original matrix
        int zeroCount = 0;
        int rows = matrix.length;
        int cols = matrix[0].length;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (matrix[i][j] == 0) {
                    zeroCount++;
                }
            }
        }

        // Create a copy for processing
        int[][] result = deepCopy(matrix);

        // Process matrix based on the selected method
        String methodUsed;
        if (useSpaceEfficient) {
            zeroMatrixSpaceEfficient(result);
            methodUsed = "Space-Efficient";
        } else {
            zeroMatrixWithSets(result);
            methodUsed = "HashSet-Based";
        }

        long endTime = System.currentTimeMillis();
        long processingTime = endTime - startTime;

        return new MatrixResult(originalMatrix, result, zeroCount, processingTime, methodUsed);
    }

    // O(n+m) space algorithm using boolean arrays
    private void zeroMatrixWithSets(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        // Track which rows and columns contain zeros
        boolean[] zeroRows = new boolean[rows];
        boolean[] zeroCols = new boolean[cols];

        // Find rows and columns with zeros
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (matrix[i][j] == 0) {
                    zeroRows[i] = true;
                    zeroCols[j] = true;
                }
            }
        }

        // Zero out identified rows
        for (int i = 0; i < rows; i++) {
            if (zeroRows[i]) {
                for (int j = 0; j < cols; j++) {
                    matrix[i][j] = 0;
                }
            }
        }

        // Zero out identified columns
        for (int j = 0; j < cols; j++) {
            if (zeroCols[j]) {
                for (int i = 0; i < rows; i++) {
                    matrix[i][j] = 0;
                }
            }
        }
    }

    // O(1) space algorithm using first row and column as markers
    private void zeroMatrixSpaceEfficient(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        // Check if first row and column have zeros
        boolean firstRowHasZero = false;
        boolean firstColHasZero = false;

        // Check first row
        for (int j = 0; j < cols; j++) {
            if (matrix[0][j] == 0) {
                firstRowHasZero = true;
                break;
            }
        }

        // Check first column
        for (int i = 0; i < rows; i++) {
            if (matrix[i][0] == 0) {
                firstColHasZero = true;
                break;
            }
        }

        // Use first row and column as markers
        for (int i = 1; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                if (matrix[i][j] == 0) {
                    matrix[i][0] = 0;
                    matrix[0][j] = 0;
                }
            }
        }

        // Zero out rows based on markers in first column
        for (int i = 1; i < rows; i++) {
            if (matrix[i][0] == 0) {
                for (int j = 0; j < cols; j++) {
                    matrix[i][j] = 0;
                }
            }
        }

        // Zero out columns based on markers in first row
        for (int j = 1; j < cols; j++) {
            if (matrix[0][j] == 0) {
                for (int i = 0; i < rows; i++) {
                    matrix[i][j] = 0;
                }
            }
        }

        // Zero out first row if needed
        if (firstRowHasZero) {
            for (int j = 0; j < cols; j++) {
                matrix[0][j] = 0;
            }
        }

        // Zero out first column if needed
        if (firstColHasZero) {
            for (int i = 0; i < rows; i++) {
                matrix[i][0] = 0;
            }
        }
    }

    // Helper method to create a deep copy of a matrix
    private int[][] deepCopy(int[][] matrix) {
        if (matrix == null) {
            return null;
        }

        int[][] copy = new int[matrix.length][];
        for (int i = 0; i < matrix.length; i++) {
            if (matrix[i] != null) {
                copy[i] = new int[matrix[i].length];
                System.arraycopy(matrix[i], 0, copy[i], 0, matrix[i].length);
            }
        }
        return copy;
