    public List<VersaoOrcamento> filterVersions(List<VersaoOrcamento> versions, String status, Timestamp fromDate, Timestamp toDate) {
        if (versions == null) {
            return new ArrayList<>();
        }

        List<VersaoOrcamento> filtered = new ArrayList<>();

        for (VersaoOrcamento version : versions) {
            if (version == null) {
                continue;
            }

            // Filter by status if provided
            if (status != null && !status.equals(version.getIdtStatus())) {
                continue;
            }

            // Filter by date range if provided
            if (fromDate != null && (version.getDataVigencia() == null || version.getDataVigencia().before(fromDate))) {
                continue;
            }

            if (toDate != null && (version.getDataVigencia() == null || version.getDataVigencia().after(toDate))) {
                continue;
            }

            filtered.add(version);
        }

        return filtered;
    }

    public BudgetVersionAnalysis analyzeVersions(List<VersaoOrcamento> versions) {
        BudgetVersionAnalysis analysis = new BudgetVersionAnalysis();

        if (versions == null || versions.isEmpty()) {
            return analysis;
        }

        int approved = 0;
        int rejected = 0;
        int pending = 0;
        Timestamp earliest = null;
        Timestamp latest = null;

        for (VersaoOrcamento version : versions) {
            if (version == null) {
                continue;
            }

            // Count by status
            String status = version.getIdtStatus();
            if ("A".equals(status)) {
                approved++;
            } else if ("R".equals(status)) {
                rejected++;
            } else if ("P".equals(status)) {
                pending++;
            }

            // Track earliest and latest dates
            Timestamp date = version.getDataVigencia();
            if (date != null) {
                if (earliest == null || date.before(earliest)) {
                    earliest = date;
                }
                if (latest == null || date.after(latest)) {
                    latest = date;
                }
            }
        }

        analysis.setTotalCount(versions.size());
        analysis.setApprovedCount(approved);
        analysis.setRejectedCount(rejected);
        analysis.setPendingCount(pending);
        analysis.setEarliestDate(earliest);
        analysis.setLatestDate(latest);

        return analysis;
    }
}

