class BSTValidator {
    public static boolean isValidBST(BSTNode root) {
        return isValidBSTHelper(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    private static boolean isValidBSTHelper(BSTNode node, long minVal, long maxVal) {
        // Base case: an empty tree is a valid BST
        if (node == null) {
            return true;
        }

        // Check if current node violates BST property
        if (node.value <= minVal || node.value >= maxVal) {
            return false;
        }

        // Recursively validate left and right subtrees with updated bounds
        return isValidBSTHelper(node.left, minVal, node.value) && 
               isValidBSTHelper(node.right, node.value, maxVal);
    }
}

