import java.util.*;
import java.util.concurrent.*;

class MessageProducer {
    private BlockingQueue<String> messageQueue;
    private List<String> sentMessages;
    private int maxRetries;
    private long retryDelayMs;

    public MessageProducer() {
        this(new LinkedBlockingQueue<>(), 3, 100);
    }

    public MessageProducer(BlockingQueue<String> messageQueue, int maxRetries, long retryDelayMs) {
        this.messageQueue = messageQueue;
        this.sentMessages = new ArrayList<>();
        this.maxRetries = maxRetries;
        this.retryDelayMs = retryDelayMs;
    }

    public void sendMessages(String prefix, int count) {
        for (int i = 1; i <= count; i++) {
            String message = prefix + " " + i;

            boolean messageAdded = false;
            int attempts = 0;

            while (!messageAdded && attempts <= maxRetries) {
                try {
                    if (attempts > 0) {
                        Thread.sleep(retryDelayMs);
                    }

                    messageAdded = messageQueue.offer(message, 100, TimeUnit.MILLISECONDS);
                    if (messageAdded) {
                        sentMessages.add(message);
                    }

                    attempts++;
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        }
    }

    public BlockingQueue<String> getMessageQueue() {
        return messageQueue;
    }

    public List<String> getSentMessages() {
