    private List<OctaveChangeListener> listeners;

    public PianoOctaveManager(int initialOctave, int minOctave, int maxOctave) {
        if (minOctave > maxOctave) {
            throw new IllegalArgumentException("minOctave cannot be greater than maxOctave");
        }

        this.minOctave = minOctave;
        this.maxOctave = maxOctave;
        this.listeners = new ArrayList<>();

        // Clamp initialOctave to be within [minOctave, maxOctave] inclusive
        if (initialOctave < minOctave) {
            this.currentOctave = minOctave;
        } else if (initialOctave > maxOctave) {
            this.currentOctave = maxOctave;
        } else {
            this.currentOctave = initialOctave;
        }
    }

    public int getCurrentOctave() {
        return currentOctave;
    }

    public void setCurrentOctave(int octave) {
        int oldOctave = this.currentOctave;
        if (octave < minOctave) {
            this.currentOctave = minOctave;
        } else if (octave > maxOctave) {
            this.currentOctave = maxOctave;
        } else {
            this.currentOctave = octave;
        }

        if (this.currentOctave != oldOctave) {
            notifyListeners(oldOctave, this.currentOctave);
        }
    }

    private void setCurrentOctave(int oldOctave, int newOctave) {
        this.currentOctave = newOctave;
        notifyListeners(oldOctave, newOctave);
    }

    private void notifyListeners(int oldOctave, int newOctave) {
        for (OctaveChangeListener listener : listeners) {
            listener.octaveChanged(oldOctave, newOctave);
        }
    }

    public int getMinOctave() {
        return minOctave;
    }

    public int getMaxOctave() {
        return maxOctave;
    }

    public boolean incrementOctave() {
        if (currentOctave < maxOctave) {
            int oldOctave = currentOctave;
            setCurrentOctave(oldOctave, currentOctave + 1);
            return true;
        }
        return false;
    }

    public boolean decrementOctave() {
        if (currentOctave > minOctave) {
            int oldOctave = currentOctave;
            setCurrentOctave(oldOctave, currentOctave - 1);
            return true;
        }
        return false;
    }

    public void addOctaveChangeListener(OctaveChangeListener listener) {
        listeners.add(listener);
    }

    public void removeOctaveChangeListener(OctaveChangeListener listener) {
        listeners.remove(listener);
    }

    public interface OctaveChangeListener {
        void octaveChanged(int oldOctave, int newOctave);
    }
}

