import java.util.Comparator;

class EnhancedMergeSort {

    public Integer[] sortIntegers(Integer[] array) {
        // Handle edge cases
        if (array == null) {
            throw new IllegalArgumentException("Array cannot be null");
        }

        if (array.length <= 1) {
            return array;
        }

        // Create a copy to avoid modifying the original array
        Integer[] result = array.clone();
        mergeSort(result, 0, result.length - 1);
        return result;
    }

    private void mergeSort(Integer[] array, int left, int right) {
        if (left < right) {
            // Find the middle point
            int middle = left + (right - left) / 2;

            // Recursively sort first and second halves
            mergeSort(array, left, middle);
            mergeSort(array, middle + 1, right);

            // Merge the sorted halves
            merge(array, left, middle, right);
        }
    }

    private void merge(Integer[] array, int left, int middle, int right) {
        // Calculate sizes of subarrays
        int leftSize = middle - left + 1;
        int rightSize = right - middle;

        // Create temporary arrays
        Integer[] leftArray = new Integer[leftSize];
        Integer[] rightArray = new Integer[rightSize];

        // Copy data to temporary arrays
        for (int i = 0; i < leftSize; i++) {
            leftArray[i] = array[left + i];
        }
        for (int j = 0; j < rightSize; j++) {
            rightArray[j] = array[middle + 1 + j];
        }

        // Merge the temporary arrays back into array[left..right]
        int i = 0, j = 0, k = left;

        while (i < leftSize && j < rightSize) {
            if (leftArray[i] <= rightArray[j]) {
                array[k] = leftArray[i];
                i++;
            } else {
                array[k] = rightArray[j];
                j++;
            }
            k++;
        }

        // Copy remaining elements of leftArray[], if any
        while (i < leftSize) {
            array[k] = leftArray[i];
            i++;
            k++;
        }

        // Copy remaining elements of rightArray[], if any
        while (j < rightSize) {
            array[k] = rightArray[j];
            j++;
            k++;
        }
    }
}

