        // Return false if permission is null
        if (permission == null) {
            return false;
        }

        // Check if URI matches exactly
        if (!permission.getUri().equals(requestUri)) {
            return false;
        }

        // Check if method matches case-insensitively
        return permission.getMethod().equalsIgnoreCase(requestMethod);
    }
}

