import java.util.List;

class PermissionInfo {
    private String uri;
    private String method;

    public PermissionInfo(String uri, String method) {
        this.uri = uri;
        this.method = method;
    }

    public String getUri() {
        return uri;
    }

    public String getMethod() {
        return method;
    }

    @Override
    public String toString() {
        return "PermissionInfo{uri='" + uri + "', method='" + method + "'}";
    }
}

class PermissionValidator {
    public boolean hasPermission(List<PermissionInfo> permissions, String requestUri, String requestMethod) {
        // Return false if permissions list is null or empty
        if (permissions == null || permissions.isEmpty()) {
            return false;
        }

        // Check each permission in the list
        for (PermissionInfo permission : permissions) {
            // Skip null permissions
            if (permission == null) {
                continue;
            }

            // Check if URI matches exactly
            if (permission.getUri().equals(requestUri)) {
                // Check if method matches case-insensitively
                if (permission.getMethod().equalsIgnoreCase(requestMethod)) {
                    return true;
                }
            }
        }

        // No matching permission found
        return false;
    }
}

