import java.util.ArrayList;
import java.util.List;

class WebServiceClient {
    public List<String> getPagedResults(String baseUrl, String endpoint, String whereClause, 
                                      int firstResult, int maxResults) {
        return new ArrayList<>();
    }

    private String simulateHttpRequest(String urlString) {
        if (urlString.contains("/schema")) {
            return "<xs:element name=\"Openbravo\">";
        } else if (urlString.contains("/dal")) {
            return "<Types>";
        } else if (urlString.contains("ADColumn")) {
            // Parse firstResult and maxResults from URL query string
            int firstResult = 0;
            int maxResults = 50;

            String[] parts = urlString.split("\\?");
            if (parts.length > 1) {
                String queryParams = parts[1];
                String[] params = queryParams.split("&");
                for (String param : params) {
                    if (param.startsWith("firstResult=")) {
                        firstResult = Integer.parseInt(param.split("=")[1]);
                    } else if (param.startsWith("maxResults=")) {
                        maxResults = Integer.parseInt(param.split("=")[1]);
                    }
                }
            }

            // Generate simulated XML response
            StringBuilder response = new StringBuilder();
            response.append("<ADColumns>");

            int itemCount = Math.min(maxResults, 50);
            for (int i = 0; i < itemCount; i++) {
                int id = firstResult + i;
                response.append("<ADColumn id=\"").append(id).append("\">Column").append(id).append("</ADColumn>");
            }

            response.append("</ADColumns>");
            return response.toString();
        } else {
            throw new RuntimeException("Unknown endpoint: " + urlString);
        }
    }
}

