import java.util.*;
import java.util.function.Function;

class MessageProcessor {
    private final Set<String> processedMessageIds;
    private final Map<String, Function<String, String>> handlers;
    private final List<RoutingRule> routingRules;

    private static class RoutingRule {
        String pattern;
        String handlerKey;

        RoutingRule(String pattern, String handlerKey) {
            this.pattern = pattern;
            this.handlerKey = handlerKey;
        }
    }

    public MessageProcessor() {
        // Initialize all data structures
        processedMessageIds = new HashSet<>();
        handlers = new HashMap<>();
        routingRules = new ArrayList<>();
    }

    public String processMessage(String messageId, String messageType, String content) {
        // Process a single message with deduplication
        if (processedMessageIds.contains(messageId)) {
            return "Message already processed";
        }

        String handlerKey = findHandlerKey(messageType);
        if (handlerKey == null) {
            return "No handler found for message type: " + messageType;
        }

        if (!handlers.containsKey(handlerKey)) {
            return "No handler found for message type: " + messageType;
        }

        processedMessageIds.add(messageId);
        Function<String, String> handler = handlers.get(handlerKey);
        return handler.apply(content);
    }

    public void addHandler(String messageType, Function<String, String> handler) {
        handlers.put(messageType, handler);
    }

    public void addRoutingRule(String pattern, String handlerKey) {
        routingRules.add(new RoutingRule(pattern, handlerKey));
    }

    public String findHandlerKey(String path) {
        for (RoutingRule rule : routingRules) {
            if (matchesPattern(path, rule.pattern)) {
                return rule.handlerKey;
            }
        }
        return null;
    }

    private boolean matchesPattern(String path, String pattern) {
        String[] pathSegments = path.split("/");
        String[] patternSegments = pattern.split("/");

        int pathIndex = 0;
        int patternIndex = 0;

        while (pathIndex < pathSegments.length && patternIndex < patternSegments.length) {
            if (patternSegments[patternIndex].equals("#")) {
                // # matches any sequence of characters
                // Find the next non-# pattern segment
                patternIndex++;
                if (patternIndex >= patternSegments.length) {
                    // # is the last segment, it matches the rest of the path
                    return true;
                }

                // Look for the next pattern segment in the remaining path
                while (pathIndex < pathSegments.length) {
                    if (pathSegments[pathIndex].equals(patternSegments[patternIndex])) {
                        // Found a match, continue with normal matching
                        break;
                    }
                    pathIndex++;
                }

                if (pathIndex >= pathSegments.length) {
                    // Reached end of path without finding the next pattern segment
                    return false;
                }
            } else if (pathSegments[pathIndex].equals(patternSegments[patternIndex])) {
                // Exact match
                pathIndex++;
                patternIndex++;
            } else {
                // No match
                return false;
            }
        }

        // Check if we've consumed all pattern segments
        // If there are remaining pattern segments, they should all be #
        while (patternIndex < patternSegments.length && patternSegments[patternIndex].equals("#")) {
            patternIndex++;
        }

        return patternIndex >= patternSegments.length && pathIndex >= pathSegments.length;
    }
}

