        condition = lock.newCondition();
        isSignalled = false;
    }

    public boolean waitWithDeadline(int waitSeconds) {
        lock.lock();
        try {
            // Calculate the absolute deadline
            Date deadline = new Date(System.currentTimeMillis() + waitSeconds * 1000L);

            // Wait until signalled or deadline reached
            while (!isSignalled) {
                try {
                    if (!condition.awaitUntil(deadline)) {
                        // Timeout occurred
                        return false;
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return false;
                }
            }

            // We were signalled
            return true;
        } finally {
            isSignalled = false;
            lock.unlock();
        }
    }

    public void notifyAllThreads() {
        lock.lock();
        try {
            isSignalled = true;
            condition.signalAll();
        } finally {
            lock.unlock();
        }
    }
