    private List<Node> globalLongestPath;

    public List<Node> findLongestPath(Node root) {
        if (root == null) {
            return new ArrayList<>();
        }

        globalLongestPath = new ArrayList<>();
        dfs(root);
        return globalLongestPath;
    }

    private int dfs(Node node) {
        if (node == null) {
            return 0;
        }

        // Track the two deepest paths from children
        int firstMaxDepth = 0;
        int secondMaxDepth = 0;
        Node firstMaxChild = null;
        Node secondMaxChild = null;

        // Process all children
        for (Node child : node.children) {
            int childDepth = dfs(child);

            if (childDepth > firstMaxDepth) {
                secondMaxDepth = firstMaxDepth;
                secondMaxChild = firstMaxChild;
                firstMaxDepth = childDepth;
                firstMaxChild = child;
            } else if (childDepth > secondMaxDepth) {
                secondMaxDepth = childDepth;
                secondMaxChild = child;
            }
        }

        // Update global longest path if combining two deepest paths through current node is longer
        if (firstMaxDepth + secondMaxDepth + 1 > globalLongestPath.size()) {
            globalLongestPath.clear();

            // Build the path: secondMaxChild's path -> current node -> firstMaxChild's path
            List<Node> secondPath = new ArrayList<>();
            if (secondMaxChild != null) {
                buildPathToLeaf(secondMaxChild, secondPath);
                Collections.reverse(secondPath);
            }

            globalLongestPath.addAll(secondPath);
            globalLongestPath.add(node);

            List<Node> firstPath = new ArrayList<>();
            if (firstMaxChild != null) {
                buildPathToLeaf(firstMaxChild, firstPath);
            }
            globalLongestPath.addAll(firstPath);
        }

        // Return the depth of the longest path from this node to a leaf
        return firstMaxDepth + 1;
    }

    private void buildPathToLeaf(Node node, List<Node> path) {
        if (node == null) {
            return;
        }

        path.add(node);

        if (!node.children.isEmpty()) {
            Node deepestChild = null;
            int maxDepth = -1;

            for (Node child : node.children) {
