    private int getDepth(Node node) {
        if (node == null) {
            return 0;
        }

        int maxChildDepth = 0;
        for (Node child : node.children) {
            maxChildDepth = Math.max(maxChildDepth, getDepth(child));
        }

        return maxChildDepth + 1;
    }
