public class TreePathAnalyzer {

    public static class Node {
        int data;
        List<Node> children;

        public Node(int data) {
            this.data = data;
            this.children = new ArrayList<>();
        }

        public void addChild(Node child) {
            this.children.add(child);
        }

        @Override
        public String toString() {
            return String.valueOf(data);
        }
    }

    private List<Node> globalLongestPath;

    public List<Node> findLongestPath(Node root) {
        if (root == null) {
            return new ArrayList<>();
        }

        globalLongestPath = new ArrayList<>();
        dfs(root);
        return globalLongestPath;
    }

    // Returns an array where index 0 is the max depth and index 1 is the node at that depth
    private int[] dfs(Node node) {
        if (node == null) {
            return new int[]{0, -1}; // depth, placeholder
        }

        // Track the two deepest paths from children
        int firstMaxDepth = 0;
        int secondMaxDepth = 0;
        Node firstMaxChild = null;

        // Process all children - each node visited exactly once
        for (Node child : node.children) {
            int[] childResult = dfs(child);
            int childDepth = childResult[0];

            if (childDepth > firstMaxDepth) {
                secondMaxDepth = firstMaxDepth;
                firstMaxDepth = childDepth;
                firstMaxChild = child;
            } else if (childDepth > secondMaxDepth) {
                secondMaxDepth = childDepth;
            }
        }

        // Update global longest path if combining two deepest paths through current node is longer
        int currentPathLength = firstMaxDepth + secondMaxDepth + 1;
        if (currentPathLength > globalLongestPath.size()) {
            globalLongestPath.clear();

            // Build the path through current node
            List<Node> firstPath = new ArrayList<>();
            List<Node> secondPath = new ArrayList<>();

            // Get path from first deepest child
            if (firstMaxChild != null) {
                buildPathFromLeaf(firstMaxChild, firstPath);
            }

            // Get path from second deepest child (we need to find it)
            if (secondMaxDepth > 0) {
                for (Node child : node.children) {
                    if (child != firstMaxChild && getDepth(child) == secondMaxDepth) {
                        buildPathFromLeaf(child, secondPath);
                        break;
                    }
                }
            }

            // Combine paths: secondPath (reversed) + current node + firstPath
            Collections.reverse(secondPath);
            globalLongestPath.addAll(secondPath);
            globalLongestPath.add(node);
            globalLongestPath.addAll(firstPath);
        }

        // Return the depth of the longest path from this node to a leaf
        return new int[]{firstMaxDepth + 1, node.data};
    }

    private void buildPathFromLeaf(Node node, List<Node> path) {
        path.add(node);

        if (!node.children.isEmpty()) {
            Node deepestChild = null;
            int maxDepth = -1;

            for (Node child : node.children) {
                int depth = getDepth(child);
                if (depth > maxDepth) {
                    maxDepth = depth;
                    deepestChild = child;
                }
            }

            if (deepestChild != null) {
                buildPathFromLeaf(deepestChild, path);
            }
        }
    }

    private int getDepth(Node node) {
        if (node == null) {
            return 0;
        }

        int maxChildDepth = 0;
        for (Node child : node.children) {
            maxChildDepth = Math.max(maxChildDepth, getDepth(child));
        }

