    }
}

public class UserManager {
    private List<User> users;
    private Map<String, Integer> failedAttempts;
    private Map<String, Boolean> lockedAccounts;
    private static final int MAX_ATTEMPTS = 3;

    public UserManager() {
        this.users = new ArrayList<>();
        this.failedAttempts = new HashMap<>();
        this.lockedAccounts = new HashMap<>();
    }

    public Map<String, Object> registerUser(User user) {
        Map<String, Object> result = new HashMap<>();

        // Check if username is empty
        if (user.getUsername() == null || user.getUsername().trim().isEmpty()) {
            result.put("success", false);
            result.put("message", "Username cannot be empty");
            return result;
        }

        // Check if password is empty
        if (user.getPassword() == null || user.getPassword().trim().isEmpty()) {
            result.put("success", false);
            result.put("message", "Password cannot be empty");
            return result;
        }

        // Check if username is unique (case-insensitive)
        for (User existingUser : users) {
            if (existingUser.getUsername().equalsIgnoreCase(user.getUsername())) {
                result.put("success", false);
                result.put("message", "Username already exists");
                return result;
            }
        }

        // If all checks pass, add the user
        users.add(user);
        result.put("success", true);
        result.put("message", "User registered successfully");
        return result;
    }

    public Map<String, Object> loginUser(String username, String password) {
        Map<String, Object> result = new HashMap<>();

        // Find the user
        User foundUser = null;
        for (User user : users) {
            if (user.getUsername().equalsIgnoreCase(username)) {
                foundUser = user;
                break;
            }
        }

        // Check if user exists
        if (foundUser == null) {
            result.put("success", false);
            result.put("message", "Invalid credentials");
            return result;
        }

        // Check if account is locked
        if (Boolean.TRUE.equals(lockedAccounts.getOrDefault(username.toLowerCase(), false))) {
            result.put("success", false);
            result.put("message", "Account locked due to too many failed attempts");
            return result;
        }

        // Check credentials
        if (foundUser.getPassword().equals(password)) {
            // Successful login
            failedAttempts.remove(username.toLowerCase());
            lockedAccounts.remove(username.toLowerCase());
            result.put("success", true);
            result.put("message", "Login successful");
            result.put("user", foundUser);
            return result;
        } else {
            // Failed login attempt
            int attempts = failedAttempts.getOrDefault(username.toLowerCase(), 0) + 1;
            failedAttempts.put(username.toLowerCase(), attempts);

            if (attempts >= MAX_ATTEMPTS) {
                lockedAccounts.put(username.toLowerCase(), true);
                result.put("success", false);
                result.put("message", "Account locked due to too many failed attempts");
                return result;
            } else {
                int attemptsRemaining = MAX_ATTEMPTS - attempts;
                result.put("success", false);
                result.put("message", "Invalid credentials");
                result.put("attemptsRemaining", attemptsRemaining);
                return result;
            }
        }
    }
}

