            result.put("user", foundUser);
            return result;
        } else {
            // Failed login attempt
            int attempts = failedAttempts.getOrDefault(username.toLowerCase(), 0) + 1;
            failedAttempts.put(username.toLowerCase(), attempts);

            if (attempts >= MAX_ATTEMPTS) {
                lockedAccounts.put(username.toLowerCase(), true);
                result.put("success", false);
                result.put("message", "Account locked due to too many failed attempts");
                return result;
            } else {
                int attemptsRemaining = MAX_ATTEMPTS - attempts;
                result.put("success", false);
                result.put("message", "Invalid credentials");
                result.put("attemptsRemaining", attemptsRemaining);
                return result;
            }
        }
    }

    public List<User> searchUsers(String username, String email, int page, int pageSize) {
        // Filter users based on criteria
        List<User> filteredUsers = new ArrayList<>();

        for (User user : users) {
            boolean usernameMatch = (username == null || username.isEmpty()) || 
                                   user.getUsername().toLowerCase().contains(username.toLowerCase());
            boolean emailMatch = (email == null || email.isEmpty()) || 
                                user.getEmail().toLowerCase().contains(email.toLowerCase());

            if (usernameMatch && emailMatch) {
                filteredUsers.add(user);
            }
        }

        // Handle pagination
        if (filteredUsers.isEmpty() || page < 1 || pageSize < 1) {
            return new ArrayList<>();
        }

        int startIndex = (page - 1) * pageSize;
        int endIndex = Math.min(startIndex + pageSize, filteredUsers.size());

        // Return empty list if requested page exceeds available data
        if (startIndex >= filteredUsers.size()) {
            return new ArrayList<>();
        }

        return new ArrayList<>(filteredUsers.subList(startIndex, endIndex));
    }
}
