import java.util.*;

class PathFinder {

    public static class PathAnalysis {
        public final int totalPaths;
        public final int maxPathLength;
        public final int minPathLength;
        public final List<String> samplePath;

        public PathAnalysis(int totalPaths, int maxPathLength, int minPathLength, List<String> samplePath) {
            this.totalPaths = totalPaths;
            this.maxPathLength = maxPathLength;
            this.minPathLength = minPathLength;
            this.samplePath = samplePath;
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            sb.append("Total Paths: ").append(totalPaths).append("\n");
            sb.append("Max Path Length: ").append(maxPathLength).append("\n");
            sb.append("Min Path Length: ").append(minPathLength).append("\n");
            sb.append("Sample Path: ").append(samplePath);
            return sb.toString();
        }
    }

    public PathAnalysis findUniquePathsWithAnalysis(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return new PathAnalysis(0, 0, 0, new ArrayList<>());
        }

        int rows = grid.length;
        int cols = grid[0].length;

        // If start or end cell is an obstacle, no paths are possible
        if (grid[0][0] == 1 || grid[rows-1][cols-1] == 1) {
            return new PathAnalysis(0, 0, 0, new ArrayList<>());
        }

        // DP table to store number of paths to each cell
        int[][] dp = new int[rows][cols];

        // Initialize first cell
        dp[0][0] = 1;

        // Fill first row
        for (int j = 1; j < cols; j++) {
            if (grid[0][j] == 0) {
                dp[0][j] = dp[0][j-1];
            } else {
                dp[0][j] = 0; // Obstacle
            }
        }

        // Fill first column
        for (int i = 1; i < rows; i++) {
            if (grid[i][0] == 0) {
                dp[i][0] = dp[i-1][0];
            } else {
                dp[i][0] = 0; // Obstacle
            }
        }

        // Fill the rest of the dp table
        for (int i = 1; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                if (grid[i][j] == 0) { // Not an obstacle
                    dp[i][j] = dp[i-1][j] + dp[i][j-1];
                } else {
                    dp[i][j] = 0; // Obstacle
                }
            }
        }

        // If no paths exist
        if (dp[rows-1][cols-1] == 0) {
            return new PathAnalysis(0, 0, 0, new ArrayList<>());
        }

        // For valid paths in a grid without obstacles, path length is constant (m+n-2)
        // But with obstacles, we need to find actual min/max path lengths
        // In this implementation, we'll use the standard path length as both min and max
        // since all valid paths in this constraint have the same structure
        int pathLength = rows + cols - 2;

        // Generate a sample path using backtracking to ensure it avoids obstacles
        List<String> samplePath = new ArrayList<>();
        List<int[]> pathCoordinates = new ArrayList<>();
        findSamplePath(grid, 0, 0, pathCoordinates);

        // Convert coordinates to string format
        for (int[] coord : pathCoordinates) {
            samplePath.add("(" + coord[0] + "," + coord[1] + ")");
        }

        return new PathAnalysis(dp[rows-1][cols-1], pathLength, pathLength, samplePath);
    }

    private boolean findSamplePath(int[][] grid, int row, int col, List<int[]> path) {
        int rows = grid.length;
        int cols = grid[0].length;

        // If current cell is an obstacle, return false
        if (grid[row][col] == 1) {
            return false;
        }

        // Add current cell to path
        path.add(new int[]{row, col});

        // If we reached the destination
        if (row == rows - 1 && col == cols - 1) {
            return true;
        }

        // Try moving right
        if (col + 1 < cols) {
            if (findSamplePath(grid, row, col + 1, path)) {
                return true;
            }
        }

        // Try moving down
        if (row + 1 < rows) {
            if (findSamplePath(grid, row + 1, col, path)) {
                return true;
            }
        }

        // If neither direction works, remove current cell from path and return false
        path.remove(path.size() - 1);
        return false;
    }
}

