    private final Set<String> validFlags;
    private final Set<String> mutuallyExclusiveGroups;

    public AdvancedFlagProcessor(Set<String> validFlags, Set<String> mutuallyExclusiveGroups) {
        this.validFlags = new HashSet<>(validFlags);
        this.mutuallyExclusiveGroups = new HashSet<>(mutuallyExclusiveGroups);
    }

    public Set<String> processFlags(String flagString) {
        Set<String> result = new HashSet<>();
        if (flagString == null || flagString.trim().isEmpty()) {
            for (String flag : validFlags) {
                result.add("|" + flag);
            }
        } else {
            // Remove the leading '|' if present
            String flagsPart = flagString.startsWith("|") ? flagString.substring(1) : flagString;

            // Split the flags by '|' to get individual flags
            Set<String> currentFlags = new HashSet<>();
            if (!flagsPart.isEmpty()) {
                String[] flagArray = flagsPart.split("\\|");
                currentFlags.addAll(Arrays.asList(flagArray));
            }

            // Check for mutually exclusive flags
            int mutuallyExclusiveCount = 0;
            for (String flag : currentFlags) {
                if (mutuallyExclusiveGroups.contains(flag)) {
                    mutuallyExclusiveCount++;
                }
            }

            if (mutuallyExclusiveCount > 1) {
                throw new IllegalArgumentException("Mutually exclusive flags detected");
            }

            // For each valid flag not already in the set, add it and create a new combination
            for (String flag : validFlags) {
                if (!currentFlags.contains(flag)) {
                    // Check if adding this flag would violate mutual exclusivity
                    if (mutuallyExclusiveGroups.contains(flag) && mutuallyExclusiveCount > 0) {
                        continue; // Skip this flag as it would violate mutual exclusivity
                    }

                    Set<String> newCombination = new HashSet<>(currentFlags);
                    newCombination.add(flag);
                    result.add("|" + String.join("|", newCombination));
                }
            }
        }
        return result;
    }
}
