import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.HashSet;

class GraphDatabaseManager {
    private Map<Long, Node> nodes;
    private Map<Long, Relationship> relationships;
    private long nextNodeId = 1;
    private long nextRelationshipId = 1;

    public GraphDatabaseManager() {
        nodes = new HashMap<>();
        relationships = new HashMap<>();
    }

    public long createNode(Map<String, Object> properties) {
        long nodeId = nextNodeId++;
        Node node = new Node(nodeId, properties);
        nodes.put(nodeId, node);
        return nodeId;
    }

    public long createRelationship(long startNodeId, long endNodeId, String type, Map<String, Object> properties) {
        if (!nodes.containsKey(startNodeId) || !nodes.containsKey(endNodeId)) {
            throw new IllegalArgumentException("Node not found: one or both specified nodes do not exist.");
        }

        long relationshipId = nextRelationshipId++;
        Relationship relationship = new Relationship(relationshipId, startNodeId, endNodeId, type, properties);
        relationships.put(relationshipId, relationship);
        return relationshipId;
    }

    public String getNodeInfo(long nodeId) {
        if (!nodes.containsKey(nodeId)) {
            throw new IllegalArgumentException("Error: Invalid node information requested.");
        }

        Node node = nodes.get(nodeId);
        StringBuilder result = new StringBuilder();

        // Node information
        result.append("Node ID: ").append(nodeId).append("\n");
        result.append("Properties: ").append(node.getProperties().toString()).append("\n");

        // Find relationships
        Set<Long> relevantRelationships = new HashSet<>();
        for (Map.Entry<Long, Relationship> entry : relationships.entrySet()) {
            Relationship rel = entry.getValue();
            if (rel.getStartNodeId() == nodeId || rel.getEndNodeId() == nodeId) {
                relevantRelationships.add(entry.getKey());
            }
        }

        if (relevantRelationships.isEmpty()) {
            result.append("Relationships: None");
        } else {
            result.append("Relationships:\n");
            for (Long relId : relevantRelationships) {
                Relationship rel = relationships.get(relId);
                result.append("  Relationship ID: ").append(relId)
                      .append(", Type: ").append(rel.getType())
                      .append(", From Node: ").append(rel.getStartNodeId())
                      .append(", To Node: ").append(rel.getEndNodeId())
                      .append(", Properties: ").append(rel.getProperties().toString())
                      .append("\n");
            }
            // Remove the last newline character
            if (result.charAt(result.length() - 1) == '\n') {
                result.deleteCharAt(result.length() - 1);
            }
        }

        return result.toString();
    }

    public void deleteNode(long nodeId) {
        if (!nodes.containsKey(nodeId)) {
            throw new IllegalArgumentException("Node not found: " + nodeId);
        }

        // Remove all relationships connected to this node
        Set<Long> relationshipsToRemove = new HashSet<>();
        for (Map.Entry<Long, Relationship> entry : relationships.entrySet()) {
            Relationship relationship = entry.getValue();
            if (relationship.getStartNodeId() == nodeId || relationship.getEndNodeId() == nodeId) {
                relationshipsToRemove.add(entry.getKey());
            }
        }

        for (Long relationshipId : relationshipsToRemove) {
            relationships.remove(relationshipId);
        }

        // Remove the node itself
        nodes.remove(nodeId);
    }

