import java.util.HashMap;
import java.util.Map;

class RegexHelper {
    public Map<String, String> generateRegexPattern(String patternType, Map<String, String> parameters) {
        Map<String, String> result = new HashMap<>();
        if ("literal".equals(patternType)) {
            String text = parameters.get("text");
            String escapedText = escapeRegexChars(text);
            result.put("pattern", escapedText);
            result.put("type", "literal");
            result.put("description", "Literal text");
        } else if ("characterClass".equals(patternType)) {
            String characterClass = parameters.get("class");
            String pattern;
            String description;

            switch (characterClass) {
                case "digit":
                    pattern = "\\d";
                    description = "Digit character class";
                    break;
                case "lowercase":
                    pattern = "[a-z]";
                    description = "Lowercase letter character class";
                    break;
                case "uppercase":
                    pattern = "[A-Z]";
                    description = "Uppercase letter character class";
                    break;
                default:
                    pattern = ".";
                    description = "Any character class";
                    break;
            }

            result.put("pattern", pattern);
            result.put("type", "characterClass");
            result.put("description", description);
        }
        return result;
    }

    private String escapeRegexChars(String input) {
        if (input == null) {
            return null;
        }

        StringBuilder escaped = new StringBuilder();
        for (char c : input.toCharArray()) {
            switch (c) {
                case '.':
                case '[':
                case ']':
                case '\\':
                case '^':
                case '$':
                case '*':
                case '+':
                case '?':
                case '{':
                case '}':
                case '(':
                case ')':
                case '|':
                    escaped.append('\\');
                    escaped.append(c);
                    break;
                default:
                    escaped.append(c);
                    break;
            }
        }
        return escaped.toString();
    }
}

