import java.util.ArrayList;
import java.util.Collections;

class CargoOptimizer {

    public static int calculateMaxTrips(ArrayList<Integer> weights, int capacity) {
        if (weights == null || weights.isEmpty()) {
            return 0;
        }

        // Create a copy to avoid modifying the original list
        ArrayList<Integer> remainingWeights = new ArrayList<>(weights);

        // Sort in descending order to process heaviest items first
        Collections.sort(remainingWeights, Collections.reverseOrder());

        int trips = 0;
        int i = 0;

        // First pass: Process items that can travel alone (weight >= capacity)
        while (i < remainingWeights.size()) {
            if (remainingWeights.get(i) >= capacity) {
                trips++;
                remainingWeights.remove(i);
            } else {
                break; // Since sorted, no more items can travel alone
            }
        }

        // Second pass: Process groups of remaining items
        while (!remainingWeights.isEmpty()) {
            // Try to form a group that satisfies the condition
            boolean groupFound = false;

            // Try different group sizes starting from largest possible
            for (int groupSize = remainingWeights.size(); groupSize >= 1; groupSize--) {
                if (groupSize > 0 && remainingWeights.get(0) * groupSize >= capacity) {
                    // Remove the group items
                    for (int j = 0; j < groupSize && j < remainingWeights.size(); j++) {
                        remainingWeights.remove(0);
                    }
                    trips++;
                    groupFound = true;
                    break;
                }
            }

            // If no valid group found, we can't make more trips
            if (!groupFound) {
                break;
            }
        }

        return trips;
    }
}

