            while (groupSize <= remainingWeights.size() && heaviestItem * groupSize < capacity) {
                groupSize++;
            }

            // If we can form a valid group
            if (groupSize <= remainingWeights.size()) {
                // Remove the group items
                for (int j = 0; j < groupSize; j++) {
                    remainingWeights.remove(0);
                }
                trips++;
            } else {
                // Cannot form a valid group with remaining items
                break;
            }
        }

        return trips;
    }
}
