public class FileOperationsManager {

    /**
     * Writes each string in the list as a separate line to the specified file using UTF-8 encoding.
     * 
     * @param filePath the path to the file to write to
     * @param lines the list of strings to write to the file
     * @param append if true, append to the file; if false, overwrite the file
     * @return true if the operation succeeds, false otherwise
     */
    public boolean writeToFile(String filePath, List<String> lines, boolean append) {
        try {
            // Create parent directories if they don't exist
            Path path = Paths.get(filePath);
            Files.createDirectories(path.getParent());

            // Write to file with appropriate mode (append or overwrite)
            try (BufferedWriter writer = new BufferedWriter(
                    new OutputStreamWriter(
                            new FileOutputStream(filePath, append), 
                            StandardCharsets.UTF_8))) {

                for (String line : lines) {
                    writer.write(line);
                    writer.newLine();
                }
            }

            return true;
        } catch (IOException e) {
            return false;
        }
