import java.util.*;
import java.util.stream.Collectors;

public class UserInfoManager {

    public static class PhoneContact {
        private String name;
        private String phoneNumber;
        private String email;

        public PhoneContact(String name, String phoneNumber, String email) {
            this.name = name;
            this.phoneNumber = phoneNumber;
            this.email = email;
        }

        public String getName() {
            return name;
        }

        public String getPhoneNumber() {
            return phoneNumber;
        }

        public String getEmail() {
            return email;
        }
    }

    public static class UserInfo {
        private String name;
        private String formattedPhoneNumber;
        private String email;

        public UserInfo(String name, String formattedPhoneNumber, String email) {
            this.name = name;
            this.formattedPhoneNumber = formattedPhoneNumber;
            this.email = email;
        }

        public String getName() {
            return name;
        }

        public String getFormattedPhoneNumber() {
            return formattedPhoneNumber;
        }

        public String getEmail() {
            return email;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            UserInfo userInfo = (UserInfo) obj;
            return Objects.equals(name, userInfo.name) &&
                   Objects.equals(formattedPhoneNumber, userInfo.formattedPhoneNumber) &&
                   Objects.equals(email, userInfo.email);
        }

        @Override
        public int hashCode() {
            return Objects.hash(name, formattedPhoneNumber, email);
        }
    }

    public Map<String, List<UserInfo>> processContacts(List<PhoneContact> contacts) {
        List<UserInfo> processedContacts = new ArrayList<>();

        for (PhoneContact contact : contacts) {
            if (contact != null && isValidContact(contact)) {
                String formattedPhone = formatPhoneNumber(contact.getPhoneNumber());
                UserInfo userInfo = new UserInfo(contact.getName(), formattedPhone, contact.getEmail());
                processedContacts.add(userInfo);
            }
        }

        Map<String, List<UserInfo>> result = new HashMap<>();
        result.put("successful", processedContacts);
        return result;
    }

    private boolean isValidContact(PhoneContact contact) {
        return contact.getName() != null && !contact.getName().trim().isEmpty() &&
               contact.getPhoneNumber() != null && !contact.getPhoneNumber().trim().isEmpty() &&
               contact.getEmail() != null && !contact.getEmail().trim().isEmpty() &&
               isValidEmail(contact.getEmail());
    }

    private boolean isValidEmail(String email) {
        return email.contains("@") && email.contains(".");
    }

    private String formatPhoneNumber(String phoneNumber) {
        // Remove all non-digit characters
        String digitsOnly = phoneNumber.replaceAll("[^0-9]", "");

        // Format as (XXX) XXX-XXXX if it has 10 digits
        if (digitsOnly.length() == 10) {
            return String.format("(%s) %s-%s", 
                digitsOnly.substring(0, 3), 
                digitsOnly.substring(3, 6), 
                digitsOnly.substring(6, 10));
        }

        // If not 10 digits, return as is
        return phoneNumber;
    }
}

