        for (int o = 0; o < outputSize; o++) {
            // Get bias for this output neuron
            double sum = weights[outputWeightsStartIndex + o * (hiddenSize + 1)];

            // Add weighted inputs from hidden layer
            for (int h = 0; h < hiddenSize; h++) {
