                    clicks++;
                }
            }
        }

        return clicks;
    }

    private void dfsReveal(int r, int c) {
        // Mark current cell as visited
        visited[r][c] = true;

        // If current cell is not a zero, don't expand further
        if (map[r][c] != '0') {
            return;
        }

        // For zero cells, reveal all 8 neighbors
        for (int d = 0; d < 8; d++) {
            int nr = r + dirR[d];
            int nc = c + dirC[d];

            // Check bounds and if already visited
            if (nr >= 1 && nr < map.length - 1 && nc >= 1 && nc < map[0].length - 1 
                && !visited[nr][nc] && map[nr][nc] != '*') {
                dfsReveal(nr, nc);
            }
        }
    }
}
