import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

class ClientTO {
    private Long id;
    private String firstName;
    private String lastName;
    private String email;
    private String phone;

    // Default constructor
    public ClientTO() {}

    // Constructor without id (for new clients)
    public ClientTO(String firstName, String lastName, String email, String phone) {
        this.firstName = firstName;
        this.lastName = lastName;
        this.email = email;
        this.phone = phone;
    }

    // Constructor with all parameters
    public ClientTO(Long id, String firstName, String lastName, String email, String phone) {
        this.id = id;
        this.firstName = firstName;
        this.lastName = lastName;
        this.email = email;
        this.phone = phone;
    }

    // Getters
    public Long getId() {
        return id;
    }

    public String getFirstName() {
        return firstName;
    }

    public String getLastName() {
        return lastName;
    }

    public String getEmail() {
        return email;
    }

    public String getPhone() {
        return phone;
    }

    // Setters
    public void setId(Long id) {
        this.id = id;
    }

    public void setFirstName(String firstName) {
        this.firstName = firstName;
    }

    public void setLastName(String lastName) {
        this.lastName = lastName;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public void setPhone(String phone) {
        this.phone = phone;
    }

    @Override
    public String toString() {
        return "ClientTO{" +
                "id=" + id +
                ", firstName='" + firstName + '\'' +
                ", lastName='" + lastName + '\'' +
                ", email='" + email + '\'' +
                ", phone='" + phone + '\'' +
                '}';
    }
}

class ClientManager {
    private final Map<Long, ClientTO> clients = new ConcurrentHashMap<>();
    private final AtomicLong idGenerator = new AtomicLong(1);

    /**
     * Creates a new client with a unique ID
     * @param clientTO the client data transfer object
     * @return the created client with assigned ID
     */
    public ClientTO createClient(ClientTO clientTO) {
        // Generate unique ID
        Long newId = idGenerator.getAndIncrement();

        // Create new client with assigned ID
        ClientTO newClient = new ClientTO(
            newId,
            clientTO.getFirstName(),
            clientTO.getLastName(),
            clientTO.getEmail(),
            clientTO.getPhone()
        );

        // Store the client
        clients.put(newId, newClient);

        return newClient;
    }

    /**
     * Retrieves a client by ID
     * @param id the client ID
     * @return the client if found, null otherwise
     */
    public ClientTO getClient(Long id) {
        return clients.get(id);
    }

    /**
     * Gets all clients
     * @return a collection of all clients
     */
    public Collection<ClientTO> getAllClients() {
        return clients.values();
    }

    /**
     * Gets the number of clients
     * @return the client count
     */
    public int getClientCount() {
        return clients.size();
    }
}

