import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.util.stream.Collectors;

class DataProcessor {

    public static Map<String, Object> processEcommerceData(String categoriesJson, String cartJson) {
        Map<String, Object> result = new HashMap<>();

        // Parse categories JSON (assuming format: ["cat1", "cat2", "cat3"])
        List<String> categoryNames = new ArrayList<>();
        if (categoriesJson != null && !categoriesJson.isEmpty()) {
            String cleanCategories = categoriesJson.trim();
            if (cleanCategories.startsWith("[") && cleanCategories.endsWith("]")) {
                String content = cleanCategories.substring(1, cleanCategories.length() - 1);
                if (!content.isEmpty()) {
                    String[] categories = content.split(",");
                    for (String category : categories) {
                        String trimmed = category.trim();
                        if (trimmed.startsWith("\"") && trimmed.endsWith("\"")) {
                            trimmed = trimmed.substring(1, trimmed.length() - 1);
                        }
                        categoryNames.add(trimmed);
                    }
                }
            }
        }

        // Parse cart JSON (assuming format: {"item1": 5, "item2": 3})
        int totalCartItems = 0;
        if (cartJson != null && !cartJson.isEmpty()) {
            String cleanCart = cartJson.trim();
            if (cleanCart.startsWith("{") && cleanCart.endsWith("}")) {
                String content = cleanCart.substring(1, cleanCart.length() - 1);
                if (!content.isEmpty()) {
                    String[] items = content.split(",");
                    for (String item : items) {
                        String[] parts = item.split(":");
                        if (parts.length == 2) {
                            try {
                                int quantity = Integer.parseInt(parts[1].trim());
                                totalCartItems += quantity;
                            } catch (NumberFormatException e) {
                                // Ignore invalid quantities
                            }
                        }
                    }
                }
            }
        }

        // Calculate results
        int categoryCount = categoryNames.size();
        boolean hasEmptyCategories = categoryNames.stream().anyMatch(name -> name.isEmpty());
        List<Integer> categoryNameLengths = categoryNames.stream().map(String::length).collect(Collectors.toList());

        // Populate result map
        result.put("categoryCount", categoryCount);
        result.put("totalCartItems", totalCartItems);
