class EnhancedSpotLight {
    private PointLight pointLight;
    private Vector3 direction;
    private double cutoff;
    private double outerCutoff;
    private double falloffExponent;

    public EnhancedSpotLight() {
        this.pointLight = new PointLight();
        this.direction = new Vector3();
        this.cutoff = 0.0;
        this.outerCutoff = 45.0;
        this.falloffExponent = 1.0;
    }

    public EnhancedSpotLight(PointLight pointLight, Vector3 direction, double cutoff, double outerCutoff, double falloffExponent) {
        this.pointLight = pointLight;
        this.direction = direction;
        this.cutoff = cutoff;
        this.outerCutoff = outerCutoff;
        this.falloffExponent = falloffExponent;
    }

    public PointLight getPointLight() {
        return pointLight;
    }

    public void setPointLight(PointLight pointLight) {
        if (pointLight == null) {
            throw new IllegalArgumentException("PointLight cannot be null");
        }
        this.pointLight = pointLight;
    }

    public Vector3 getDirection() {
        return direction;
    }

    public void setDirection(Vector3 direction) {
        if (direction == null) {
            throw new IllegalArgumentException("Direction cannot be null");
        }
        this.direction = direction;
    }

    public double getCutoff() {
        return cutoff;
    }

    public void setCutoff(double cutoff) {
        if (cutoff < 0 || cutoff > 90) {
            throw new IllegalArgumentException("Cutoff must be between 0 and 90 degrees");
        }
        this.cutoff = cutoff;
    }

    public double getOuterCutoff() {
        return outerCutoff;
    }

    public void setOuterCutoff(double outerCutoff) {
        if (outerCutoff < 0 || outerCutoff > 90) {
            throw new IllegalArgumentException("OuterCutoff must be between 0 and 90 degrees");
        }
        if (outerCutoff <= this.cutoff) {
            throw new IllegalArgumentException("OuterCutoff must be greater than cutoff");
        }
        this.outerCutoff = outerCutoff;
    }

    public double getFalloffExponent() {
        return falloffExponent;
    }

    public void setFalloffExponent(double falloffExponent) {
        if (falloffExponent <= 0) {
            throw new IllegalArgumentException("FalloffExponent must be positive");
        }
        this.falloffExponent = falloffExponent;
    }

    public double calculateIntensity(Vector3 point) {
        // Calculate the direction from the light to the point
        Vector3 lightToPoint = point.sub(pointLight.getPosition());
        double distance = lightToPoint.length();

        // Calculate distance attenuation
        double distanceAttenuation = 1.0 / (pointLight.getConstant() + 
                                          pointLight.getLinear() * distance + 
                                          pointLight.getExponent() * distance * distance);

        // If the point is at the same position as the light, return full intensity (distance only)
        if (distance == 0) {
            return pointLight.getIntensity() * distanceAttenuation;
        }

        // Normalize both vectors
        Vector3 lightDirection = lightToPoint.normalized();
        Vector3 spotDirection = this.direction.normalized();

        // Calculate the cosine of the angle between the light direction and spot direction
        double cosAngle = lightDirection.dot(spotDirection);

        // Convert angles from degrees to radians
        double cutoffRad = Math.toRadians(cutoff);
        double outerCutoffRad = Math.toRadians(outerCutoff);

        // Calculate cosine values for the angles
        double cosCutoff = Math.cos(cutoffRad);
        double cosOuterCutoff = Math.cos(outerCutoffRad);

        // If outside the outer cutoff, return zero intensity
        if (cosAngle < cosOuterCutoff) {
            return 0.0;
        }

        // If inside the inner cutoff, return full angular intensity
        double angularAttenuation;
        if (cosAngle > cosCutoff) {
            angularAttenuation = 1.0;
        } else {
            // Smooth transition between inner and outer cutoff
            // Map the cosine value to [0, 1] range
            double intensityFactor = (cosAngle - cosOuterCutoff) / (cosCutoff - cosOuterCutoff);

            // Apply falloff exponent
            angularAttenuation = Math.pow(intensityFactor, falloffExponent);
        }

        // Combine distance and angular attenuation
        return pointLight.getIntensity() * distanceAttenuation * angularAttenuation;
    }
}

