import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.Map;
import java.util.Queue;

class PlayerInfo {
    private String playerId;
    private int score;
    private boolean active;

    public PlayerInfo(String playerId, int score) {
        this.playerId = playerId;
        this.score = score;
        this.active = true;
    }

    public String getPlayerId() {
        return playerId;
    }

    public int getScore() {
        return score;
    }

    public void setScore(int score) {
        this.score = score;
    }

    public boolean isActive() {
        return active;
    }

    public void setActive(boolean active) {
        this.active = active;
    }

    @Override
    public String toString() {
        return "PlayerInfo{playerId='" + playerId + "', score=" + score + ", active=" + active + "}";
    }
}

public class PlayerManagementSystem {
    private final Map<String, PlayerInfo> players;
    private final Queue<String> playerQueue;

    public PlayerManagementSystem() {
        this.players = new ConcurrentHashMap<>();
        this.playerQueue = new ConcurrentLinkedQueue<>();
    }

    public synchronized boolean registerPlayer(String playerId, int score) {
        if (players.containsKey(playerId)) {
            return false; // Player already exists
        }
        PlayerInfo player = new PlayerInfo(playerId, score);
        players.put(playerId, player);
        playerQueue.offer(playerId);
        return true; // Player registered successfully
    }

    public PlayerInfo getPlayer(String playerId) {
        PlayerInfo player = players.get(playerId);
        if (player != null && player.isActive()) {
            return player;
        }
        return null;
    }

    public synchronized boolean updateScore(String playerId, int newScore) {
        PlayerInfo player = players.get(playerId);
        if (player != null && player.isActive()) {
            player.setScore(newScore);
            return true;
        }
        return false;
    }

    public synchronized boolean removePlayer(String playerId) {
        PlayerInfo player = players.get(playerId);
        if (player != null) {
            player.setActive(false);
            players.remove(playerId);
            playerQueue.remove(playerId);
            return true;
        }
        return false;
    }

    public synchronized String getNextPlayer() {
        if (playerQueue.isEmpty()) {
            return null;
        }

        String playerId = playerQueue.poll();
        // Check if the player is still active
        PlayerInfo player = players.get(playerId);
        if (player != null && player.isActive()) {
            playerQueue.offer(playerId); // Move to back of queue
