class TreeAnalyzer {
    public Map<String, Integer> analyzeTree(TreeNode root) {
        Map<String, Integer> result = new HashMap<>();

        // Count nodes
        int nodeCount = countNodes(root);
        result.put("nodeCount", nodeCount);

        // Calculate max ancestor difference
        int maxDiff = 0;
        if (root != null) {
            maxDiff = findMaxDiff(root, root.val, root.val);
        }
        result.put("maxDiff", maxDiff);

        return result;
    }

    private int countNodes(TreeNode node) {
        if (node == null) {
            return 0;
        }
        return 1 + countNodes(node.left) + countNodes(node.right);
    }

    private int findMaxDiff(TreeNode node, int minAncestor, int maxAncestor) {
        if (node == null) {
            return 0;
        }

        // Calculate difference with current node and ancestors
        int diff = Math.max(Math.abs(node.val - minAncestor), Math.abs(node.val - maxAncestor));

        // Update min and max ancestors for children
        minAncestor = Math.min(minAncestor, node.val);
        maxAncestor = Math.max(maxAncestor, node.val);

        // Recursively find max difference in subtrees
        int leftDiff = findMaxDiff(node.left, minAncestor, maxAncestor);
        int rightDiff = findMaxDiff(node.right, minAncestor, maxAncestor);

        // Return maximum of current diff and diffs from subtrees
        return Math.max(diff, Math.max(leftDiff, rightDiff));
    }
}

