    int val;
    TreeNode left;
    TreeNode right;

    TreeNode() {}

    TreeNode(int val) {
        this.val = val;
    }

    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class TreeAnalyzer {
    public Map<String, Integer> analyzeTree(TreeNode root) {
        Map<String, Integer> result = new HashMap<>();

        if (root == null) {
            result.put("nodeCount", 0);
            result.put("maxDiff", 0);
            result.put("minDiff", 0);
            result.put("avgDiff", 0);
            return result;
        }

        // Use a helper class to store statistics during traversal
        TreeStats stats = new TreeStats();
        traverseTree(root, root.val, root.val, stats);

        result.put("nodeCount", stats.nodeCount);
        result.put("maxDiff", stats.maxDiff);
        result.put("minDiff", stats.minDiff);
        result.put("avgDiff", stats.nodeCount > 0 ? stats.sumDiff / stats.nodeCount : 0);

        return result;
    }

    private void traverseTree(TreeNode node, int minAncestor, int maxAncestor, TreeStats stats) {
        if (node == null) {
            return;
        }

        // Update node count
        stats.nodeCount++;

        // Calculate difference with current node and ancestors
        int diff = Math.max(Math.abs(node.val - minAncestor), Math.abs(node.val - maxAncestor));

        // Update statistics
        stats.sumDiff += diff;
        stats.maxDiff = Math.max(stats.maxDiff, diff);
        if (stats.nodeCount > 1) { // Only update minDiff after the first node
            stats.minDiff = Math.min(stats.minDiff, diff);
        } else {
            stats.minDiff = 0; // First node has no ancestor difference
        }

        // Update min and max ancestors for children
        minAncestor = Math.min(minAncestor, node.val);
        maxAncestor = Math.max(maxAncestor, node.val);

        // Recursively traverse subtrees
        traverseTree(node.left, minAncestor, maxAncestor, stats);
        traverseTree(node.right, minAncestor, maxAncestor, stats);
    }

    // Helper class to store tree statistics
    private static class TreeStats {
        int nodeCount = 0;
        int maxDiff = 0;
        int minDiff = Integer.MAX_VALUE;
        int sumDiff = 0;
    }
}
