import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

class ThreadStatistics {
    private int totalThreads;
    private int completedTasks;
    private int interruptedTasks;

    public ThreadStatistics(int totalThreads, int completedTasks, int interruptedTasks) {
        this.totalThreads = totalThreads;
        this.completedTasks = completedTasks;
        this.interruptedTasks = interruptedTasks;
    }

    public int getTotalThreads() {
        return totalThreads;
    }

    public int getCompletedTasks() {
        return completedTasks;
    }

    public int getInterruptedTasks() {
        return interruptedTasks;
    }
}

class ThreadManager {
    public ThreadStatistics manageThreads(int threadCount, long workDurationMs, long interruptAfterMs) {
        List<Thread> threads = new ArrayList<>();
        AtomicInteger completedTasks = new AtomicInteger(0);
        AtomicInteger interruptedTasks = new AtomicInteger(0);
        AtomicBoolean isInterrupted = new AtomicBoolean(false);

        // Create and start the specified number of worker threads
        for (int i = 0; i < threadCount; i++) {
            Thread worker = new Thread(() -> {
                System.out.println(Thread.currentThread().getName());
                try {
                    Thread.sleep(workDurationMs);
                    // Increment completed tasks counter when sleep completes successfully
                    if (!isInterrupted.get()) {
                        completedTasks.incrementAndGet();
                    }
                } catch (InterruptedException e) {
                    // Increment interrupted tasks counter when interrupted during sleep
                    isInterrupted.set(true);
                    interruptedTasks.incrementAndGet();
                    Thread.currentThread().interrupt();
                }
            });
            threads.add(worker);
            worker.start();
        }

        // Create and start interrupter thread if interruptAfterMs is positive
        Thread interrupter = null;
        if (interruptAfterMs > 0) {
            interrupter = new Thread(() -> {
                try {
                    Thread.sleep(interruptAfterMs);
                    // Interrupt all worker threads that are still alive
                    for (Thread thread : threads) {
                        if (thread.isAlive()) {
                            thread.interrupt();
                        }
                    }
                    isInterrupted.set(true);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
            interrupter.start();
        }

        // Wait for all threads to complete
        for (Thread thread : threads) {
            try {
                thread.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        // Wait for interrupter thread to complete if it was started
        if (interrupter != null) {
            try {
                interrupter.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        // Return statistics with total thread count, completed tasks, and interrupted tasks
        return new ThreadStatistics(threadCount, completedTasks.get(), interruptedTasks.get());
    }
}

