public class RedditFeedAnalyzer {
    public String analyzeAndFormatFeed(List<RedditFeedItem> feedItems, int minScore) {
        if (feedItems == null || feedItems.isEmpty()) {
            return "No feed items to analyze";
        }

        int count = 0;
        int totalScore = 0;
        int totalComments = 0;

        for (RedditFeedItem item : feedItems) {
            if (item.getScore() >= minScore) {
                count++;
                totalScore += item.getScore();
                totalComments += item.getNumComments();
            }
        }

        DecimalFormat df = new DecimalFormat("0.00");
        String averageScore = df.format(count > 0 ? (double) totalScore / count : 0.00);
        String averageComments = df.format(count > 0 ? (double) totalComments / count : 0.00);

        return "Feed Analysis Summary:Total items: " + count + "\nAverage score: " + averageScore + "\nAverage comments: " + averageComments;
    }
}

