import java.util.ArrayList;
import java.util.Collections;

class BinaryTree<T extends Comparable<T>> {
    private Node<T> root;

    private static class Node<T> {
        T data;
        Node<T> left, right;

        Node(T data) {
            this.data = data;
        }
    }

    public void insert(T data) {
        root = insertRec(root, data);
    }

    private Node<T> insertRec(Node<T> node, T data) {
        if (node == null) {
            return new Node<>(data);
        }

        if (data.compareTo(node.data) < 0) {
            node.left = insertRec(node.left, data);
        } else if (data.compareTo(node.data) > 0) {
            node.right = insertRec(node.right, data);
        }

        return node;
    }

    public List<T> inOrderTraversal() {
        List<T> result = new ArrayList<>();
        inOrderRec(root, result);
        return result;
    }

    private void inOrderRec(Node<T> node, List<T> result) {
        if (node != null) {
            inOrderRec(node.left, result);
            result.add(node.data);
            inOrderRec(node.right, result);
        }
    }

    // Helper method to set the root directly (needed for balanced loading)
    public void setRoot(Node<T> root) {
        this.root = root;
    }

    // Helper method to get the root (needed for testing)
    public Node<T> getRoot() {
        return root;
    }
}

class AdvancedTreeLoader<T extends Comparable<T>> {
    public void load(BinaryTree<T> tree, List<T> data, boolean shouldSort) {
        if (shouldSort) {
            List<T> sortedData = new ArrayList<>(data);
            Collections.sort(sortedData);
            tree.setRoot(loadBalanced(sortedData, 0, sortedData.size() - 1));
        } else {
            for (T item : data) {
                tree.insert(item);
            }
        }
    }

    private Node<T> loadBalanced(List<T> sortedData, int start, int end) {
        if (start > end) {
            return null;
        }

        int mid = start + (end - start) / 2;
        Node<T> node = new Node<>(sortedData.get(mid));

        node.left = loadBalanced(sortedData, start, mid - 1);
        node.right = loadBalanced(sortedData, mid + 1, end);

        return node;
    }
}

