            inOrderRec(node.left, result);
            result.add(node.data);
            inOrderRec(node.right, result);
        }
    }

    // Helper method to set the root directly (needed for balanced loading)
    public void setRoot(Node<T> root) {
        this.root = root;
    }

    // Helper method to get the root (needed for testing)
    public Node<T> getRoot() {
        return root;
    }

    // Helper method to clear the tree
    public void clear() {
        this.root = null;
    }
}

class AdvancedTreeLoader<T extends Comparable<T>> {
    public void load(BinaryTree<T> tree, List<T> data, boolean shouldSort, boolean allowDuplicates) {
        // Clear the tree first to ensure empty lists result in empty tree
        tree.clear();

        if (data.isEmpty()) {
            return; // Empty list results in empty tree
        }

        if (!allowDuplicates) {
            checkForDuplicates(data);
        }

        if (shouldSort) {
            List<T> sortedData = new ArrayList<>(data);
            Collections.sort(sortedData);
            tree.setRoot(loadBalanced(sortedData, 0, sortedData.size() - 1));
        } else {
            // Insert data in original order from the list
            for (T item : data) {
                tree.insert(item);
            }
        }
    }

    private void checkForDuplicates(List<T> data) {
        Set<T> seen = new HashSet<>();
        for (T item : data) {
            if (!seen.add(item)) {
                throw new IllegalArgumentException("Duplicate elements found: " + item);
            }
        }
    }

    private Node<T> loadBalanced(List<T> sortedData, int start, int end) {
        if (start > end) {
            return null;
        }

        int mid = start + (end - start) / 2;
        Node<T> node = new Node<>(sortedData.get(mid));

        node.left = loadBalanced(sortedData, start, mid - 1);
        node.right = loadBalanced(sortedData, mid + 1, end);

        return node;
    }
}
