import java.util.List;
import java.util.ArrayList;

public class PaginationProcessor<T> {
    private List<T> dataset;
    private int defaultPageSize;

    public PaginationProcessor(List<T> dataset, int defaultPageSize) {
        this.dataset = dataset != null ? dataset : new ArrayList<>();
        this.defaultPageSize = defaultPageSize > 0 ? defaultPageSize : 10;
    }

    public PaginationResult<T> getPaginatedData(int pageNumber, int itemsPerPage) {
        // Validate inputs
        int currentPage = pageNumber > 0 ? pageNumber : 1;
        int pageSize = itemsPerPage > 0 ? itemsPerPage : defaultPageSize;

        // Calculate total items and pages
        int totalItems = dataset.size();
        int totalPages = (int) Math.ceil((double) totalItems / pageSize);

        // Handle edge case where there's no data
        if (totalItems == 0) {
            return new PaginationResult<>(new ArrayList<>(), currentPage, pageSize, 0, 0);
        }

        // Ensure current page doesn't exceed total pages
        if (currentPage > totalPages) {
            currentPage = totalPages;
        }

        // Calculate start and end indices
        int startIndex = (currentPage - 1) * pageSize;
        int endIndex = Math.min(startIndex + pageSize, totalItems);

        // Extract page data
        List<T> pageData = new ArrayList<>();
        if (startIndex < totalItems) {
            pageData = dataset.subList(startIndex, endIndex);
        }

        return new PaginationResult<>(pageData, currentPage, pageSize, totalPages, totalItems);
    }

    public PaginationResult<T> getPaginatedData(int pageNumber) {
        return getPaginatedData(pageNumber, defaultPageSize);
    }

    public static class PaginationResult<T> {
        private List<T> data;
        private int currentPage;
        private int itemsPerPage;
        private int totalPages;
        private int totalItems;

        public PaginationResult(List<T> data, int currentPage, int itemsPerPage, int totalPages, int totalItems) {
            this.data = data;
            this.currentPage = currentPage;
            this.itemsPerPage = itemsPerPage;
            this.totalPages = totalPages;
            this.totalItems = totalItems;
        }

        public List<T> getData() {
            return data;
        }

        public int getCurrentPage() {
            return currentPage;
        }

        public int getItemsPerPage() {
            return itemsPerPage;
        }

        public int getTotalPages() {
            return totalPages;
        }

        public int getTotalItems() {
            return totalItems;
        }

        @Override
        public String toString() {
            return "PaginationResult{" +
                    "data=" + data +
                    ", currentPage=" + currentPage +
                    ", itemsPerPage=" + itemsPerPage +
                    ", totalPages=" + totalPages +
                    ", totalItems=" + totalItems +
                    '}';
        }
    }
}

