import java.io.*;
import java.nio.file.*;
import java.util.List;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

public class FileHandler {
    public static Object handleFileOperation(String operationType, List<Path> files, Path targetDirectory, String fileName) {
        if ("upload".equals(operationType)) {
            try {
                // Create target directory if it doesn't exist
                Files.createDirectories(targetDirectory);

                // Copy all files to the target directory
                int uploadedCount = 0;
                for (Path file : files) {
                    if (Files.exists(file)) {
                        Path targetFile = targetDirectory.resolve(file.getFileName());
                        Files.copy(file, targetFile, StandardCopyOption.REPLACE_EXISTING);
                        uploadedCount++;
                    }
                }

                return uploadedCount + " files uploaded successfully";
            } catch (IOException e) {
                return "Upload failed: " + e.getMessage();
            }
        } else if ("download".equals(operationType)) {
            try {
                Path filePath = targetDirectory.resolve(fileName);
                return Files.readAllBytes(filePath);
            } catch (IOException e) {
                return "Download failed: " + e.getMessage();
            }
        } else if ("zip".equals(operationType)) {
            try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
                 ZipOutputStream zos = new ZipOutputStream(baos)) {

                for (Path file : files) {
                    if (Files.exists(file)) {
                        // Add file to zip
                        ZipEntry zipEntry = new ZipEntry(file.getFileName().toString());
                        zos.putNextEntry(zipEntry);

                        // Copy file content to zip
                        Files.copy(file, zos);
                        zos.closeEntry();
                    }
                }

                zos.finish();
                return baos.toByteArray();
            } catch (IOException e) {
                return "Zip creation failed: " + e.getMessage();
            }
        }
        return null;
    }

    // Overloaded method for backward compatibility
    public static Object handleFileOperation(String operationType, List<Path> files, Path targetDirectory) {
        return handleFileOperation(operationType, files, targetDirectory, null);
    }
}

