    /**
     * Creates a consumer that wraps an operation and verifies the expected exception is thrown.
     * 
     * @param <T> the type of the input to the operation
     * @param <E> the type of the expected exception
     * @param expectedExceptionClass the expected exception class
     * @param exceptionValidator optional validator to check custom criteria on the thrown exception
     * @param operation the operation to wrap
     * @return a consumer that wraps the operation and verifies the expected exception
     */
    public static <T, E extends Exception> Consumer<T> enhancedExceptionExpectation(
            Class<E> expectedExceptionClass, 
            Predicate<E> exceptionValidator, 
            Consumer<T> operation) {

        Objects.requireNonNull(expectedExceptionClass, "Expected exception class must not be null");
        Objects.requireNonNull(operation, "Operation must not be null");

        return (T input) -> {
            try {
                operation.accept(input);
                // If no exception was thrown, throw AssertionError
                throw new AssertionError(
                    "Expected exception of type " + expectedExceptionClass.getSimpleName() + 
                    " but no exception was thrown.");
            } catch (Exception actualException) {
                // Check if the actual exception is an instance of the expected exception class
                if (!expectedExceptionClass.isInstance(actualException)) {
                    throw new AssertionError(
                        "Expected exception of type " + expectedExceptionClass.getSimpleName() + 
                        " but got " + actualException.getClass().getSimpleName() + " instead.");
                }

                // If validator is provided, check the exception against it
                if (exceptionValidator != null) {
                    @SuppressWarnings("unchecked")
                    E expectedException = (E) actualException;
                    if (!exceptionValidator.test(expectedException)) {
                        throw new AssertionError(
                            "Thrown exception of type " + actualException.getClass().getSimpleName() + 
                            " failed validation.");
                    }
                }
                // If we reach here, the exception type matches and validation passed (if applicable)
            }
        };
    }

    // Overloaded method without exception validator
    public static <T, E extends Exception> Consumer<T> enhancedExceptionExpectation(
            Class<E> expectedExceptionClass, 
            Consumer<T> operation) {
        return enhancedExceptionExpectation(expectedExceptionClass, null, operation);
    }
