import java.text.NumberFormat;

class EggDropSolver {
    public static int solveEggDrop(int k, int n) {
        // Validate input parameters
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive");
        }

        // Create a 2D DP table where dp[i][j] represents minimum attempts
        // needed with i eggs and j floors
        int[][] dp = new int[k + 1][n + 1];

        // Base cases:
        // With 1 egg, we need j attempts for j floors (linear search)
        for (int j = 1; j <= n; j++) {
            dp[1][j] = j;
        }

        // With 1 floor, we need 1 attempt regardless of number of eggs
        // With 0 floors, we need 0 attempts
        for (int i = 1; i <= k; i++) {
            dp[i][1] = 1;
            dp[i][0] = 0;
        }

        // Fill the DP table for remaining cases
        for (int i = 2; i <= k; i++) {
            for (int j = 2; j <= n; j++) {
                dp[i][j] = Integer.MAX_VALUE;

                // Try dropping from each floor x (1 to j)
                for (int x = 1; x <= j; x++) {
                    // If egg breaks: we have i-1 eggs and x-1 floors below
                    // If egg doesn't break: we have i eggs and j-x floors above
                    int attempts = 1 + Math.max(dp[i-1][x-1], dp[i][j-x]);
                    dp[i][j] = Math.min(dp[i][j], attempts);
                }
            }
        }

        return dp[k][n];
    }

    public static int solveEggDropMath(int k, int n) {
        // Validate input parameters
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive");
        }

        // Mathematical approach using binomial coefficients
        // Find minimum attempts m such that C(m,1) + C(m,2) + ... + C(m,k) >= n
        int attempts = 0;
        while (binomialSum(attempts, k) < n) {
            attempts++;
        }

        return attempts;
    }

    private static long binomialSum(int m, int k) {
        // Calculate sum of C(m,1) + C(m,2) + ... + C(m,k)
        long sum = 0;
        long binomial = 1;

        for (int i = 1; i <= k && i <= m; i++) {
            binomial = binomial * (m - i + 1) / i;
            sum += binomial;
        }

        return sum;
    }

    public static int solveEggDropBinarySearch(int k, int n) {
        // Validate input parameters
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive");
        }

        // Binary search approach with memoization
        int[][] memo = new int[k + 1][n + 1];
        for (int i = 0; i <= k; i++) {
            for (int j = 0; j <= n; j++) {
                memo[i][j] = -1;
            }
        }

        int low = 1;
        int high = n;
        int result = n;

        while (low <= high) {
            int mid = (low + high) / 2;
            if (canFindCriticalFloor(k, mid, n, memo)) {
                result = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        return result;
    }

    private static boolean canFindCriticalFloor(int eggs, int attempts, int floors, int[][] memo) {
        if (eggs == 1) return attempts >= floors;
        if (attempts == 1) return floors <= 1;
        if (floors == 0) return true;
        if (floors == 1) return true;
        if (memo[eggs][floors] != -1) {
            return memo[eggs][floors] == 1;
        }

        // Calculate maximum floors we can check with 'eggs' eggs and 'attempts' attempts
        long maxFloors = 0;
        long combination = 1;

        for (int i = 1; i <= eggs && i <= attempts; i++) {
            combination = combination * (attempts - i + 1) / i;
            maxFloors += combination;
            if (maxFloors >= floors) {
                memo[eggs][floors] = 1;
                return true;
            }
        }

        memo[eggs][floors] = (maxFloors >= floors) ? 1 : 0;
        return maxFloors >= floors;
    }

    public static class EggDropResult {
        public final int dpResult;
        public final int mathResult;
        public final int binarySearchResult;
        public final long dpTime;
        public final long mathTime;
        public final long binarySearchTime;

        public EggDropResult(int dpResult, int mathResult, int binarySearchResult, 
                     long dpTime, long mathTime, long binarySearchTime) {
            this.dpResult = dpResult;
            this.mathResult = mathResult;
            this.binarySearchResult = binarySearchResult;
            this.dpTime = dpTime;
            this.mathTime = mathTime;
            this.binarySearchTime = binarySearchTime;
        }

        @Override
        public String toString() {
            NumberFormat formatter = NumberFormat.getInstance();
            formatter.setGroupingUsed(true);

            StringBuilder sb = new StringBuilder();
            sb.append("DP Solution: ").append(dpResult)
              .append(" (Time: ").append(formatter.format(dpTime)).append(" ns)\n");
            sb.append("Math Solution: ").append(mathResult)
              .append(" (Time: ").append(formatter.format(mathTime)).append(" ns)\n");
            sb.append("Binary Search Solution: ").append(binarySearchResult)
              .append(" (Time: ").append(formatter.format(binarySearchTime)).append(" ns)");

            return sb.toString();
        }
    }

    public static EggDropResult compareSolutions(int k, int n) {
        // Time DP solution
        long startTime = System.nanoTime();
        int dpResult = solveEggDrop(k, n);
        long dpTime = System.nanoTime() - startTime;

        // Time mathematical solution
        startTime = System.nanoTime();
        int mathResult = solveEggDropMath(k, n);
        long mathTime = System.nanoTime() - startTime;

        // Time binary search solution
        startTime = System.nanoTime();
        int binarySearchResult = solveEggDropBinarySearch(k, n);
        long binarySearchTime = System.nanoTime() - startTime;

        return new EggDropResult(dpResult, mathResult, binarySearchResult, dpTime, mathTime, binarySearchTime);
    }
}
