    public void add(String item) {
        TrieNode current = root;
        for (int i = 0; i < item.length(); i++) {
            char ch = item.charAt(i);
            current = current.addChild(ch);
        }
        current.isEndOfWord = true;
    }

    public boolean contains(String item) {
        TrieNode current = root;
        for (int i = 0; i < item.length(); i++) {
            char ch = item.charAt(i);
            current = current.getChild(ch);
            if (current == null) {
                return false;
            }
        }
        return current.isEndOfWord;
    }

    private TrieNode insert(TrieNode[] array, TrieNode element) {
        int left = 0;
        int right = array.length - 1;
        char targetChar = element.character;

        // Binary search to find the correct position
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (array[mid] == null) {
                right = mid - 1;
            } else if (array[mid].character == targetChar) {
                return array[mid];
            } else if (array[mid].character < targetChar) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        // Shift elements to make space for the new element
        for (int i = array.length - 1; i > left; i--) {
            array[i] = array[i - 1];
        }

        // Insert the new element
        array[left] = element;
        return element;
    }

    private class TrieNode {
        char character;
        boolean isEndOfWord;
        TrieNode[] children;

        public TrieNode() {
            this.children = new TrieNode[26]; // for lowercase English letters
            this.isEndOfWord = false;
        }

        public TrieNode(char character) {
            this();
            this.character = character;
        }

        public TrieNode addChild(char ch) {
            int index = ch - 'a';
            if (children[index] != null) {
                return children[index];
            }

            TrieNode newNode = new TrieNode(ch);
            insert(children, newNode);
            return newNode;
        }

        public TrieNode getChild(char ch) {
            int index = ch - 'a';
            return children[index];
        }
    }
}

