import java.util.HashMap;
import java.util.Map;

public class ServerApprovalHandler {
    private String serverName;
    private String serverIp;
    private String realmId;
    private String imageId;
    private String hardwareProfileId;
    private Map<String, String> approvalStatus;

    public ServerApprovalHandler(String serverName, String serverIp, String realmId, 
                                String imageId, String hardwareProfileId) {
        this.serverName = serverName;
        this.serverIp = serverIp;
        this.realmId = realmId;
        this.imageId = imageId;
        this.hardwareProfileId = hardwareProfileId;
        this.approvalStatus = new HashMap<>();
        this.approvalStatus.put("status", "pending");
    }

    private String validateServerName() {
        if (serverName == null) {
            return "Server name cannot be null";
        }
        if (serverName.trim().isEmpty()) {
            return "Server name cannot be empty";
        }
        if (serverName.length() > 64) {
            return "Server name cannot exceed 64 characters";
        }
        return "Valid";
    }

    private String validateIpAddress() {
        if (serverIp == null) {
            return "IP address cannot be null";
        }

        String ipRegex = "^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$";

        if (serverIp.matches(ipRegex)) {
            return "Valid";
        } else {
            return "Invalid IPv4 address format";
        }
    }

    private String validateRealmId() {
        if (realmId == null) {
            return "Realm ID cannot be null";
        }

        if (realmId.length() < 1 || realmId.length() > 36) {
            return "Realm ID must be between 1 and 36 characters";
        }

        String realmRegex = "^[a-zA-Z0-9-]+$";

        if (realmId.matches(realmRegex)) {
            return "Valid";
        } else {
            return "Realm ID can only contain alphanumeric characters and hyphens";
        }
    }

    private String validateImageId() {
        if (imageId == null) {
            return "Image ID cannot be null";
        }

        String imageRegex = "^img-[a-zA-Z0-9]{8}$";

        if (imageId.matches(imageRegex)) {
            return "Valid";
        } else {
            return "Image ID must be in format 'img-' followed by exactly 8 alphanumeric characters";
        }
    }

    private String validateHardwareProfile() {
        if (hardwareProfileId == null) {
            return "Hardware Profile ID cannot be null";
        }

        String hardwareRegex = "^hw-[a-zA-Z0-9]{4}-[a-zA-Z0-9]{4}$";

        if (hardwareProfileId.matches(hardwareRegex)) {
            return "Valid";
        } else {
            return "Hardware Profile ID must be in format 'hw-' followed by 4 alphanumerics, a hyphen, and another 4 alphanumerics";
        }
    }

    public Map<String, Object> validateConfiguration() {
        Map<String, Object> validationResult = new HashMap<>();

        boolean isValid = true;
        StringBuilder message = new StringBuilder();

        String serverNameValidation = validateServerName();
        if (!"Valid".equals(serverNameValidation)) {
            isValid = false;
            message.append(serverNameValidation).append(" ");
        }

        String ipValidation = validateIpAddress();
        if (!"Valid".equals(ipValidation)) {
            isValid = false;
            message.append(ipValidation).append(" ");
        }

        String realmValidation = validateRealmId();
        if (!"Valid".equals(realmValidation)) {
            isValid = false;
            message.append(realmValidation).append(" ");
        }

        String imageValidation = validateImageId();
        if (!"Valid".equals(imageValidation)) {
            isValid = false;
            message.append(imageValidation).append(" ");
        }

        String hardwareValidation = validateHardwareProfile();
        if (!"Valid".equals(hardwareValidation)) {
            isValid = false;
            message.append(hardwareValidation).append(" ");
        }

        validationResult.put("isValid", isValid);
        validationResult.put("message", message.toString().trim());

        return validationResult;
    }

    public Map<String, Object> processApproval() {
        Map<String, Object> result = new HashMap<>();

        Map<String, Object> validationResults = validateConfiguration();
        boolean isValid = (Boolean) validationResults.get("isValid");

        if (isValid) {
            approvalStatus.put("status", "approved");
            result.put("approvalStatus", "approved");
            result.put("message", "Server configuration approved successfully");
        } else {
            approvalStatus.put("status", "rejected");
            result.put("approvalStatus", "rejected");
            result.put("message", "Server configuration rejected due to validation errors");
        }

        result.put("validationResults", validationResults);

        return result;
    }

    // Getters for the fields
    public String getServerName() {
        return serverName;
    }

    public String getServerIp() {
        return serverIp;
    }

    public String getRealmId() {
        return realmId;
    }

    public String getImageId() {
        return imageId;
    }

    public String getHardwareProfileId() {
        return hardwareProfileId;
    }

    public Map<String, String> getApprovalStatus() {
        return approvalStatus;
    }
}
