import java.util.concurrent.CompletableFuture;
import java.util.function.Consumer;

public class EnhancedWebSocketClient {
    private WebSocketConnection connection;
    private Consumer<String> messageHandler;

    public EnhancedWebSocketClient() {
        // Default constructor
    }

    public CompletableFuture<Void> connectAsync(String url) {
        return WebSocketConnection.createAsync(url)
                .thenAccept(conn -> this.connection = conn);
    }

    public CompletableFuture<Void> sendMessageAsync(String message) {
        if (connection != null && connection.isConnected()) {
            return connection.writeAsync(message);
        } else {
            CompletableFuture<Void> future = new CompletableFuture<>();
            future.completeExceptionally(new IllegalStateException("Not connected"));
            return future;
        }
    }

    public void setMessageHandler(Consumer<String> handler) {
        this.messageHandler = handler;
        if (connection != null) {
            connection.setMessageHandler(handler);
        }
    }

    public CompletableFuture<Void> closeAsync() {
        if (connection != null) {
            return connection.closeAsync();
        } else {
            return CompletableFuture.completedFuture(null);
        }
    }

    public class WebSocketConnection {
        private boolean connected = true;
        private Consumer<String> messageHandler;

        private WebSocketConnection() {
            // Private constructor
        }

        public static CompletableFuture<WebSocketConnection> createAsync(String url) {
            WebSocketConnection connection = new WebSocketConnection();
            return CompletableFuture.completedFuture(connection);
        }

        public CompletableFuture<Void> writeAsync(String message) {
            // Simulate writing message
            return CompletableFuture.completedFuture(null);
        }

        public void setMessageHandler(Consumer<String> handler) {
            this.messageHandler = handler;
        }

        public boolean isConnected() {
            return connected;
        }

        public CompletableFuture<Void> closeAsync() {
            connected = false;
            return CompletableFuture.completedFuture(null);
        }
    }
}

