    private Map<String, Set<Contract>> tariffContracts;

    public EnhancedTariffManager() {
        this.tariffs = new HashMap<>();
        this.tariffContracts = new HashMap<>();
    }

    public void addTariff(Tariff tariff) {
        tariffs.put(tariff.getId(), tariff);
        tariffContracts.put(tariff.getId(), new HashSet<>());
    }

    public void subscribeContractToTariff(String tariffId, Contract contract) {
        if (!tariffs.containsKey(tariffId)) {
            throw new IllegalArgumentException("Tariff with ID " + tariffId + " does not exist");
        }

        tariffContracts.get(tariffId).add(contract);
    }

    public Tariff getTariff(String tariffId) {
        return tariffs.get(tariffId);
    }

    public Set<Contract> getContractsForTariff(String tariffId) {
        return tariffContracts.get(tariffId);
    }

    public Set<String> getAllTariffIds() {
        return tariffs.keySet();
    }

    public Collection<Tariff> getAllTariffs() {
        return tariffs.values();
    }
}

