        result.put("isValid", true);

        // Validate pH
        if (ph == null || ph.trim().isEmpty()) {
            result.put("isValid", false);
            result.put("error", "pH debe ser un número válido.");
            return result;
        }

        try {
            double pHValue = Double.parseDouble(ph.trim());
            if (pHValue < 0 || pHValue > 14) {
                result.put("isValid", false);
                result.put("error", "pH incorrecto, debe estar entre 0 y 14.");
                return result;
            }
        } catch (NumberFormatException e) {
            result.put("isValid", false);
            result.put("error", "pH debe ser un número válido.");
            return result;
        }

        // Validate humidity
        if (humidity == null || humidity.trim().isEmpty()) {
            result.put("isValid", false);
            result.put("error", "Humedad debe ser un número válido.");
            return result;
        }

        try {
            double humidityValue = Double.parseDouble(humidity.trim());
            if (humidityValue < 0 || humidityValue > 100) {
                result.put("isValid", false);
                result.put("error", "Humedad incorrecta, debe estar entre 0 y 100.");
                return result;
            }
        } catch (NumberFormatException e) {
            result.put("isValid", false);
            result.put("error", "Humedad debe ser un número válido.");
            return result;
        }

        // Validate fertilizer
        if (fertilizer == null || fertilizer.trim().isEmpty()) {
            result.put("isValid", false);
            result.put("error", "Abono debe ser un número válido.");
            return result;
        }

        try {
