                result.put("isValid", false);
                result.put("error", "Abono incorrecto, debe estar entre 0 y 100.");
                return result;
            }
        } catch (NumberFormatException e) {
            result.put("isValid", false);
            result.put("error", "Abono debe ser un número válido.");
            return result;
        }

        return result;
    }
}

