                if (humidityValue < 0 || humidityValue > 100) {
                    errors.append("Humedad incorrecta, debe estar entre 0 y 100. ");
                    result.put("isValid", false);
                }
            } catch (NumberFormatException e) {
                errors.append("Humedad debe ser un número válido. ");
                result.put("isValid", false);
            }
        }

        // Validate fertilizer
        if (fertilizer == null || fertilizer.trim().isEmpty()) {
            errors.append("Abono debe ser un número válido. ");
            result.put("isValid", false);
        } else {
            try {
                double fertilizerValue = Double.parseDouble(fertilizer.trim());
                if (fertilizerValue < 0 || fertilizerValue > 100) {
                    errors.append("Abono incorrecto, debe estar entre 0 y 100. ");
                    result.put("isValid", false);
                }
            } catch (NumberFormatException e) {
                errors.append("Abono debe ser un número válido. ");
                result.put("isValid", false);
            }
        }

        // Validate temperature
        if (temperature == null || temperature.trim().isEmpty()) {
            errors.append("Temperatura debe ser un número válido. ");
            result.put("isValid", false);
        } else {
            try {
                double temperatureValue = Double.parseDouble(temperature.trim());
                if (temperatureValue < -50 || temperatureValue > 100) {
                    errors.append("Temperatura fuera de rango (-50 a 100°C). ");
                    result.put("isValid", false);
                }
            } catch (NumberFormatException e) {
                errors.append("Temperatura debe ser un número válido. ");
                result.put("isValid", false);
            }
        }

        // Validate irrigation
        if (irrigation == null || irrigation.trim().isEmpty()) {
            errors.append("Riego debe ser 'ON' u 'OFF'. ");
            result.put("isValid", false);
        } else {
            String irrigationUpper = irrigation.trim().toUpperCase();
            if (!irrigationUpper.equals("ON") && !irrigationUpper.equals("OFF")) {
                errors.append("Riego debe ser 'ON' u 'OFF'. ");
                result.put("isValid", false);
            }
        }

        // If there are errors, add the error message
        if (!result.get("isValid").equals(true)) {
            result.put("error", errors.toString().trim());
        } else {
            // If all inputs are valid, set processedData
            String irrigationUpper = irrigation.trim().toUpperCase();
            String processedData = String.format("ph=%s&humedad=%s&abono=%s&temperatura=%s&riego=%s", 
                                                ph.trim(), humidity.trim(), fertilizer.trim(), 
                                                temperature.trim(), irrigationUpper);
            result.put("processedData", processedData);
        }

        return result;
    }
}

