import java.util.HashMap;
import java.util.Map;

public class UserAuthenticator {
    private Map<String, String> userDatabase;

    public UserAuthenticator() {
        userDatabase = new HashMap<>();
        // Hardcoded database with phone numbers and passwords
        userDatabase.put("1234567890", "password123");
        userDatabase.put("0987654321", "password456");
    }

    public String authenticate(String phoneNumber, String password) {
        // Check if phone number exists in database
        if (userDatabase.containsKey(phoneNumber)) {
            // Check if password matches
            if (userDatabase.get(phoneNumber).equals(password)) {
                return "Authentication successful";
            } else {
                return "Invalid password";
            }
        } else {
            return "Phone number not found";
        }
    }

    // Main method for testing
    public static void main(String[] args) {
        UserAuthenticator authenticator = new UserAuthenticator();

        // Test cases
        System.out.println(authenticator.authenticate("1234567890", "password123")); // Success
        System.out.println(authenticator.authenticate("1234567890", "wrongpassword")); // Invalid password
        System.out.println(authenticator.authenticate("1111111111", "password123")); // Not found
    }
}

