import java.util.*;

// Enum for status
enum Status {
    SUCCESS,
    FAILURE,
    PENDING
}

// Message class
class Message {
    private String content;
    private String sender;
    private long timestamp;

    public Message(String content, String sender) {
        this.content = content;
        this.sender = sender;
        this.timestamp = System.currentTimeMillis();
    }

    public String getContent() {
        return content;
    }

    public String getSender() {
        return sender;
    }

    public long getTimestamp() {
        return timestamp;
    }

    @Override
    public String toString() {
        return "Message{content='" + content + "', sender='" + sender + "', timestamp=" + timestamp + "}";
    }
}

// ProcessingResult class
class ProcessingResult {
    private Status status;
    private String message;

    public ProcessingResult(Status status, String message) {
        this.status = status;
        this.message = message;
    }

    public Status getStatus() {
        return status;
    }

    public String getMessage() {
        return message;
    }

    @Override
    public String toString() {
        return "ProcessingResult{status=" + status + ", message='" + message + "'}";
    }
}

// EnhancedMessageProcessor class
class EnhancedMessageProcessor {
    private Map<String, List<Message>> messageStore;

    public EnhancedMessageProcessor() {
        this.messageStore = new HashMap<>();
    }

    public ProcessingResult postMessage(Message message, String destination) {
        // Store the message
        messageStore.computeIfAbsent(destination, k -> new ArrayList<>()).add(message);

        // Return success result
        return new ProcessingResult(Status.SUCCESS, "Message posted successfully to " + destination);
    }

    // Helper method to retrieve messages for a destination (optional)
    public List<Message> getMessagesForDestination(String destination) {
        return messageStore.getOrDefault(destination, new ArrayList<>());
    }
}

