// EnhancedMessageProcessor class with thread-safety and message counting
class EnhancedMessageProcessor {
    private Map<String, List<Message>> messageStore;
    private Map<String, Integer> messageCountPerDestination;

    public EnhancedMessageProcessor() {
        this.messageStore = new HashMap<>();
        this.messageCountPerDestination = new HashMap<>();
    }

    public synchronized ProcessingResult postMessage(Message message, String destination) {
        // Store the message
        messageStore.computeIfAbsent(destination, k -> new ArrayList<>()).add(message);

        // Update message count for the destination
        int currentCount = messageCountPerDestination.getOrDefault(destination, 0);
        messageCountPerDestination.put(destination, currentCount + 1);

        // Calculate total messages across all destinations
