        this.messageStore = new HashMap<>();
        this.messageCountPerDestination = new HashMap<>();
    }

    public synchronized ProcessingResult postMessage(Message message, String destination) {
        // Store the message
        messageStore.computeIfAbsent(destination, k -> new ArrayList<>()).add(message);

