import java.util.logging.Logger;
import java.util.logging.Level;
import org.json.JSONObject;
import org.json.JSONArray;
import org.json.JSONException;

class DataStructureAnalyzer {
    private static final Logger logger = Logger.getLogger(DataStructureAnalyzer.class.getName());

    public static Map<String, Object> analyzeDataStructure(Object data) {
        if (data == null) {
            throw new IllegalArgumentException("Input data cannot be null");
        }

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("containsBinary", false);
        result.put("maxDepth", 0);
        result.put("totalElements", 0);

        Map<String, Integer> typeCounts = new LinkedHashMap<>();
        typeCounts.put("JSONObject", 0);
        typeCounts.put("JSONArray", 0);
        typeCounts.put("String", 0);
        typeCounts.put("Number", 0);
        typeCounts.put("Boolean", 0);
        typeCounts.put("byte[]", 0);
        typeCounts.put("Other", 0);

        result.put("typeCounts", typeCounts);

        analyzeRecursive(data, result, typeCounts, 1);

        return result;
    }

    private static void analyzeRecursive(Object data, Map<String, Object> result, 
                                       Map<String, Integer> typeCounts, int currentDepth) {
        // Update max depth
        int currentMaxDepth = (int) result.get("maxDepth");
        if (currentDepth > currentMaxDepth) {
            result.put("maxDepth", currentDepth);
        }

        // Update total elements
        int totalElements = (int) result.get("totalElements");
        result.put("totalElements", totalElements + 1);

        // Update type counts and check for binary data
        if (data instanceof String) {
            typeCounts.put("String", typeCounts.get("String") + 1);
        } else if (data instanceof Number) {
            typeCounts.put("Number", typeCounts.get("Number") + 1);
        } else if (data instanceof Boolean) {
            typeCounts.put("Boolean", typeCounts.get("Boolean") + 1);
        } else if (data instanceof byte[] || data instanceof Byte[]) {
            typeCounts.put("byte[]", typeCounts.get("byte[]") + 1);
            result.put("containsBinary", true);
        } else if (data instanceof JSONObject) {
            typeCounts.put("JSONObject", typeCounts.get("JSONObject") + 1);
            // Process JSONObject entries
            JSONObject jsonObject = (JSONObject) data;
            try {
                for (String key : jsonObject.keySet()) {
                    analyzeRecursive(key, result, typeCounts, currentDepth + 1);
                    try {
                        Object value = jsonObject.get(key);
                        if (value != null && !(value instanceof JSONObject.NULL)) {
                            analyzeRecursive(value, result, typeCounts, currentDepth + 1);
                        }
                    } catch (JSONException e) {
                        logger.log(Level.WARNING, "Error accessing JSONObject value for key: " + key, e);
                    }
                }
            } catch (Exception e) {
                logger.log(Level.WARNING, "Error iterating JSONObject keys", e);
            }
        } else if (data instanceof JSONArray) {
            typeCounts.put("JSONArray", typeCounts.get("JSONArray") + 1);
            // Process JSONArray elements
            JSONArray jsonArray = (JSONArray) data;
            try {
                for (int i = 0; i < jsonArray.length(); i++) {
                    try {
                        Object item = jsonArray.get(i);
                        if (item != null && !(item instanceof JSONObject.NULL)) {
                            analyzeRecursive(item, result, typeCounts, currentDepth + 1);
                        }
                    } catch (JSONException e) {
                        logger.log(Level.WARNING, "Error accessing JSONArray element at index: " + i, e);
                    }
                }
            } catch (Exception e) {
                logger.log(Level.WARNING, "Error iterating JSONArray elements", e);
            }
        } else if (data instanceof Map<?, ?>) {
            typeCounts.put("JSONObject", typeCounts.get("JSONObject") + 1);
            // Process map entries
            Map<?, ?> map = (Map<?, ?>) data;
            for (Map.Entry<?, ?> entry : map.entrySet()) {
                analyzeRecursive(entry.getKey(), result, typeCounts, currentDepth + 1);
                if (entry.getValue() != null) {
                    analyzeRecursive(entry.getValue(), result, typeCounts, currentDepth + 1);
                }
            }
        } else if (data instanceof List<?>) {
            typeCounts.put("JSONArray", typeCounts.get("JSONArray") + 1);
            // Process list elements
            List<?> list = (List<?>) data;
            for (Object item : list) {
                if (item != null) {
                    analyzeRecursive(item, result, typeCounts, currentDepth + 1);
                }
            }
        } else {
            typeCounts.put("Other", typeCounts.get("Other") + 1);
            // Handle other collections or arrays
            if (data instanceof Collection<?>) {
                Collection<?> collection = (Collection<?>) data;
                for (Object item : collection) {
                    if (item != null) {
                        analyzeRecursive(item, result, typeCounts, currentDepth + 1);
                    }
                }
            } else if (data.getClass().isArray() && !(data instanceof byte[] || data instanceof Byte[])) {
                if (data instanceof Object[]) {
                    Object[] array = (Object[]) data;
                    for (Object item : array) {
                        if (item != null) {
                            analyzeRecursive(item, result, typeCounts, currentDepth + 1);
                        }
                    }
                }
            }
        }
    }
}

