                        if (item != null && !(item instanceof JSONObject.NULL)) {
                            analyzeRecursive(item, result, typeCounts, currentDepth + 1);
                        }
                    } catch (JSONException e) {
                        logger.log(Level.WARNING, "Error accessing JSONArray element at index: " + i, e);
                    }
                }
            } catch (Exception e) {
                logger.log(Level.WARNING, "Error iterating JSONArray elements", e);
            }
        } else if (data instanceof Map<?, ?>) {
            typeCounts.put("JSONObject", typeCounts.get("JSONObject") + 1);
            // Process map entries
            Map<?, ?> map = (Map<?, ?>) data;
            for (Map.Entry<?, ?> entry : map.entrySet()) {
                analyzeRecursive(entry.getKey(), result, typeCounts, currentDepth + 1);
                if (entry.getValue() != null) {
                    analyzeRecursive(entry.getValue(), result, typeCounts, currentDepth + 1);
                }
            }
        } else if (data instanceof List<?>) {
            typeCounts.put("JSONArray", typeCounts.get("JSONArray") + 1);
            // Process list elements
            List<?> list = (List<?>) data;
            for (Object item : list) {
                if (item != null) {
                    analyzeRecursive(item, result, typeCounts, currentDepth + 1);
                }
            }
        } else {
            typeCounts.put("Other", typeCounts.get("Other") + 1);
            // Handle other collections or arrays
            if (data instanceof Collection<?>) {
                Collection<?> collection = (Collection<?>) data;
                for (Object item : collection) {
                    if (item != null) {
                        analyzeRecursive(item, result, typeCounts, currentDepth + 1);
                    }
                }
            } else if (data.getClass().isArray() && !(data instanceof byte[] || data instanceof Byte[])) {
                if (data instanceof Object[]) {
                    Object[] array = (Object[]) data;
                    for (Object item : array) {
                        if (item != null) {
                            analyzeRecursive(item, result, typeCounts, currentDepth + 1);
                        }
                    }
                }
            }
        }
    }
}
