import java.util.HashMap;
import java.util.List;
import java.util.ArrayList;
import java.util.Collections;

public class ThreadSafeKeyValueStore {
    private final ConcurrentHashMap<String, Object> store;
    private final ConcurrentHashMap<String, AtomicLong> accessCounters;
    private final ConcurrentHashMap<String, Long> lastAccessTimes;
    private final ConcurrentHashMap<Class<?>, AtomicLong> typeCounts;

    public ThreadSafeKeyValueStore() {
        store = new ConcurrentHashMap<>();
        accessCounters = new ConcurrentHashMap<>();
        lastAccessTimes = new ConcurrentHashMap<>();
        typeCounts = new ConcurrentHashMap<>();
    }

    public void put(String key, Object value) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        // Handle existing value removal from type count
        Object existingValue = store.get(key);
        if (existingValue != null) {
            Class<?> existingType = existingValue.getClass();
            AtomicLong existingTypeCounter = typeCounts.get(existingType);
            if (existingTypeCounter != null) {
                existingTypeCounter.decrementAndGet();
            }
        }

        // Add new value to store
        store.put(key, value);

        // Update type count for new value
        if (value != null) {
            Class<?> valueType = value.getClass();
            typeCounts.computeIfAbsent(valueType, k -> new AtomicLong(0)).incrementAndGet();
        }

        // Initialize access tracking
        accessCounters.putIfAbsent(key, new AtomicLong(0));
        lastAccessTimes.putIfAbsent(key, 0L);
    }

    public void putAll(Map<String, Object> entries) {
        if (entries == null) {
            throw new IllegalArgumentException("Entries cannot be null");
        }

        for (Map.Entry<String, Object> entry : entries.entrySet()) {
            put(entry.getKey(), entry.getValue());
        }
    }

    public Object get(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        long currentTime = System.currentTimeMillis();

        AtomicLong counter = accessCounters.get(key);
        if (counter != null) {
            counter.incrementAndGet();
        }

        lastAccessTimes.put(key, currentTime);

        return store.get(key);
    }

    public long getAccessCount(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        AtomicLong counter = accessCounters.get(key);
        return counter != null ? counter.get() : 0;
    }

    public long getLastAccessTime(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        Long lastAccessTime = lastAccessTimes.get(key);
        return lastAccessTime != null ? lastAccessTime : 0L;
    }

    public long getTypeCount(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }

        AtomicLong counter = typeCounts.get(type);
        return counter != null ? counter.get() : 0;
    }

    public List<String> findKeysByType(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }

        List<String> keys = new ArrayList<>();
        for (Map.Entry<String, Object> entry : store.entrySet()) {
            Object value = entry.getValue();
            if (value != null && type.isInstance(value)) {
                keys.add(entry.getKey());
            }
        }
        return keys;
    }

    public Statistics computeStatistics() {
        // Total entries
        int totalEntries = store.size();

        // Key with max access
        String maxAccessKey = null;
        long maxAccessCount = -1;
        for (Map.Entry<String, AtomicLong> entry : accessCounters.entrySet()) {
            long count = entry.getValue().get();
            if (count > maxAccessCount) {
                maxAccessCount = count;
                maxAccessKey = entry.getKey();
            }
        }

        // Type distribution
        Map<Class<?>, Long> typeDistribution = new HashMap<>();
        for (Map.Entry<Class<?>, AtomicLong> entry : typeCounts.entrySet()) {
            typeDistribution.put(entry.getKey(), entry.getValue().get());
        }

        // Estimated memory usage (simple estimation)
        long estimatedMemory = 0;
        for (Map.Entry<String, Object> entry : store.entrySet()) {
            // Rough estimation: key length + value reference size
            estimatedMemory += entry.getKey().length() * 2; // 2 bytes per char
            estimatedMemory += 8; // object reference
        }

        return new Statistics(totalEntries, maxAccessKey, typeDistribution, estimatedMemory);
    }

    public void clear() {
        store.clear();
        accessCounters.clear();
        lastAccessTimes.clear();
        typeCounts.clear();
    }

    public static class Statistics {
        private final int totalEntries;
        private final String mostAccessedKey;
        private final Map<Class<?>, Long> typeDistribution;
        private final long estimatedMemoryUsage;

        public Statistics(int totalEntries, String mostAccessedKey, 
                         Map<Class<?>, Long> typeDistribution, long estimatedMemoryUsage) {
            this.totalEntries = totalEntries;
            this.mostAccessedKey = mostAccessedKey;
            this.typeDistribution = Collections.unmodifiableMap(typeDistribution);
            this.estimatedMemoryUsage = estimatedMemoryUsage;
        }

        public int getTotalEntries() {
            return totalEntries;
        }

        public String getMostAccessedKey() {
            return mostAccessedKey;
        }

        public Map<Class<?>, Long> getTypeDistribution() {
            return typeDistribution;
        }

        public long getEstimatedMemoryUsage() {
            return estimatedMemoryUsage;
        }
    }
}

