import java.util.*;

public class ListDivision {

    public static List<Integer> divideLists(List<Integer> list1, List<Integer> list2) {
        if (list1 == null || list2 == null) {
            throw new IllegalArgumentException("Lists cannot be null");
        }

        if (list1.size() != list2.size()) {
            throw new IllegalArgumentException("Lists must have the same size");
        }

        List<Integer> result = new ArrayList<>();

        for (int i = 0; i < list1.size(); i++) {
            Integer num1 = list1.get(i);
            Integer num2 = list2.get(i);

            if (num1 == null || num2 == null) {
                throw new IllegalArgumentException("List elements cannot be null");
            }

            if (num2 == 0) {
                throw new ArithmeticException("Division by zero");
            }

            result.add(num1 / num2);
        }

        return result;
    }

    // Example usage (not part of the required method)
    public static void main(String[] args) {
        List<Integer> list1 = Arrays.asList(10, 20, 30, 40);
