        Category category = new Category(id, name, parentId);
        categoryMap.put(id, category);

        if (parentId == 0) {
            rootCategories.add(category);
        }

        parentChildMap.computeIfAbsent(parentId, k -> new ArrayList<>());
        parentChildMap.get(parentId).add(category);
    }

    public CatResult getItemCatList() {
        CatResult result = new CatResult();

        if (categoryMap.isEmpty()) {
            return result;
        }

        List<CategoryNode> rootNodes = new ArrayList<>();

        for (Category category : rootCategories) {
            CategoryNode node = buildCategoryTree(category);
            rootNodes.add(node);
        }

        result.setData(rootNodes);
        return result;
    }

    private CategoryNode buildCategoryTree(Category category) {
        CategoryNode node = new CategoryNode();
        node.setId(category.getId());
        node.setName(category.getName());

        List<Category> children = parentChildMap.getOrDefault(category.getId(), new ArrayList<>());
        List<CategoryNode> childNodes = new ArrayList<>();

        for (Category child : children) {
            // Only process children that actually exist in our category map
            if (categoryMap.containsKey(child.getId())) {
                CategoryNode childNode = buildCategoryTree(child);
                childNodes.add(childNode);
            }
        }

        if (!childNodes.isEmpty()) {
            node.setItems(childNodes);
        }

        return node;
    }
}

