import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.atomic.AtomicInteger;

class FactorySimulation {
    private BlockingQueue<Integer> inputStock;
    private BlockingQueue<Integer> outputStock;
    private int totalItems;
    private AtomicInteger processedItems;

    public FactorySimulation(int initialInputStock) {
        this.inputStock = new LinkedBlockingQueue<>();
        this.outputStock = new LinkedBlockingQueue<>();
        this.totalItems = initialInputStock;
        this.processedItems = new AtomicInteger(0);

        // Initialize input stock with items
        for (int i = 0; i < initialInputStock; i++) {
            inputStock.offer(i + 1);
        }
    }

    public void processItems(int itemsToProcess) {
        int itemsProcessed = 0;

        while (itemsProcessed < itemsToProcess && !inputStock.isEmpty()) {
            try {
                // Take item from input stock
                Integer item = inputStock.take();

                // Simulate processing time
                Thread.sleep(10);

                // Move to output stock
                outputStock.offer(item);

                itemsProcessed++;
                processedItems.incrementAndGet();

            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    public int getProcessedItemsCount() {
        return processedItems.get();
    }

    public int getRemainingInputStock() {
        return inputStock.size();
    }

    public int getOutputStockCount() {
        return outputStock.size();
    }

    public static void main(String[] args) {
        // Create factory with 100 items in input stock
        FactorySimulation factory = new FactorySimulation(100);

        // Process 30 items
        factory.processItems(30);

        // Print results
        System.out.println("Processed items: " + factory.getProcessedItemsCount());
        System.out.println("Remaining in input stock: " + factory.getRemainingInputStock());
        System.out.println("Items in output stock: " + factory.getOutputStockCount());
    }
}

