        int itemsProcessed = 0;

        while (itemsProcessed < itemsToProcess && !inputStock.isEmpty()) {
            try {
                // Take item from input stock
                Integer item = inputStock.take();

                // Simulate processing
                Thread.sleep(5);

                // Move to output stock
                outputStock.offer(item);

                itemsProcessed++;
                processedItems++;

            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }
}

// Version 2: Two workshops in series
class FactoryV2 extends Factory {
    private BlockingQueue<Integer> intermediateStock;

    public FactoryV2(int initialInputStock) {
        super(initialInputStock);
        this.intermediateStock = new LinkedBlockingQueue<>();
    }

    @Override
    public void processItems(int itemsToProcess) {
        int itemsProcessed = 0;

        while (itemsProcessed < itemsToProcess && !inputStock.isEmpty()) {
            try {
                // Workshop 1: input -> intermediate
                Integer item = inputStock.take();
                Thread.sleep(3); // Processing time for workshop 1
                intermediateStock.offer(item);

                // Workshop 2: intermediate -> output
                item = intermediateStock.take();
                Thread.sleep(3); // Processing time for workshop 2
                outputStock.offer(item);

                itemsProcessed++;
                processedItems++;

            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
