// FactoryPerformance class to encapsulate all simulation results
class FactoryPerformance {
    private long executionTime;
    private int processedItems;
    private int errors;
    private int inputStockLevel;
    private int outputStockLevel;
    private int[] intermediateStockLevels;
    private int factoryVersion;

    public FactoryPerformance(int factoryVersion, int intermediateStocksCount) {
        this.factoryVersion = factoryVersion;
        this.intermediateStockLevels = new int[intermediateStocksCount];
    }

    // Getters
    public long getExecutionTime() { return executionTime; }
    public int getProcessedItems() { return processedItems; }
    public int getErrors() { return errors; }
    public int getInputStockLevel() { return inputStockLevel; }
    public int getOutputStockLevel() { return outputStockLevel; }
    public int[] getIntermediateStockLevels() { return intermediateStockLevels; }
    public int getFactoryVersion() { return factoryVersion; }

    // Setters
    public void setExecutionTime(long time) { this.executionTime = time; }
    public void setProcessedItems(int count) { this.processedItems = count; }
    public void setErrors(int count) { this.errors = count; }
    public void setInputStockLevel(int level) { this.inputStockLevel = level; }
    public void setOutputStockLevel(int level) { this.outputStockLevel = level; }
    public void setIntermediateStockLevel(int index, int level) { 
        if (index < intermediateStockLevels.length) {
            this.intermediateStockLevels[index] = level; 
        }
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("Factory Performance Report (Version ").append(factoryVersion).append("):\n");
        sb.append("  Execution Time: ").append(executionTime).append(" ms\n");
        sb.append("  Processed Items: ").append(processedItems).append("\n");
