// Abstract base class for all factory versions
abstract class EnhancedFactory {
    protected BlockingQueue<Integer> inputStock;
    protected BlockingQueue<Integer> outputStock;
    protected int totalItems;
    protected volatile int processedItems;
    protected volatile int errors;
    protected int factoryVersion;

    public EnhancedFactory(int initialInputStock, int factoryVersion) {
        this.inputStock = new LinkedBlockingQueue<>();
        this.outputStock = new LinkedBlockingQueue<>();
        this.totalItems = initialInputStock;
        this.processedItems = 0;
        this.errors = 0;
        this.factoryVersion = factoryVersion;

        // Initialize input stock with items
        for (int i = 0; i < initialInputStock; i++) {
            inputStock.offer(i + 1);
        }
    }

    // Abstract methods to be implemented by each factory version
    public abstract void processItems(int itemsToProcess);
    public abstract FactoryPerformance getPerformanceMetrics();

    public synchronized int getProcessedItemsCount() {
        return processedItems;
    }

    public synchronized int getRemainingInputStock() {
        return inputStock.size();
    }

    public synchronized int getOutputStockCount() {
        return outputStock.size();
    }

    protected synchronized void incrementProcessedItems() {
        processedItems++;
    }

    protected synchronized void incrementErrors() {
        errors++;
    }

    // Factory creation method
    public static EnhancedFactory createFactory(int version, int initialInputStock) {
        switch (version) {
            case 1: return new EnhancedFactoryV1(initialInputStock);
            case 2: return new EnhancedFactoryV2(initialInputStock);
            case 3: return new EnhancedFactoryV3(initialInputStock);
            case 4: return new EnhancedFactoryV4(initialInputStock);
            default: throw new IllegalArgumentException("Invalid factory version: " + version);
        }
    }
}

