// Version 4: Four workshops (1 and 2 in parallel, followed by 3 and 4 in series)
class EnhancedFactoryV4 extends EnhancedFactory {
    private BlockingQueue<Integer> intermediateStock1;
    private BlockingQueue<Integer> intermediateStock2;
    private BlockingQueue<Integer> intermediateStock3;

    public EnhancedFactoryV4(int initialInputStock) {
        super(initialInputStock, 4);
        this.intermediateStock1 = new LinkedBlockingQueue<>();
        this.intermediateStock2 = new LinkedBlockingQueue<>();
        this.intermediateStock3 = new LinkedBlockingQueue<>();
    }

    @Override
    public void processItems(int itemsToProcess) {
        long startTime = System.currentTimeMillis();

        Thread workshop1 = new Thread(() -> {
            processParallelWorkshop(itemsToProcess / 2 + itemsToProcess % 2, 1, 2);
        });

        Thread workshop2 = new Thread(() -> {
            processParallelWorkshop(itemsToProcess / 2, 2, 2);
        });

        Thread workshop3 = new Thread(() -> {
            processSeriesWorkshop(3, 2);
        });

        Thread workshop4 = new Thread(() -> {
            processSeriesWorkshop(4, 2);
        });

        workshop1.start();
        workshop2.start();

        try {
            workshop1.join();
            workshop2.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            incrementErrors();
        }

        workshop3.start();
        try {
            workshop3.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            incrementErrors();
        }

        workshop4.start();
        try {
            workshop4.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            incrementErrors();
        }

        long endTime = System.currentTimeMillis();
    }

    private void processParallelWorkshop(int itemsToProcess, int workshopId, int processingTime) {
        int itemsProcessed = 0;
        BlockingQueue<Integer> targetStock = (workshopId == 1) ? intermediateStock1 : intermediateStock2;

        while (itemsProcessed < itemsToProcess && !inputStock.isEmpty()) {
            try {
                // Take item from input stock
                Integer item = inputStock.take();

                // Process in workshop
                Thread.sleep(processingTime);

                // Move to intermediate stock
                targetStock.offer(item);

                itemsProcessed++;
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                incrementErrors();
                break;
            } catch (Exception e) {
                incrementErrors();
            }
        }
    }

    private void processSeriesWorkshop(int workshopId, int processingTime) {
        BlockingQueue<Integer> sourceStock = (workshopId == 3) ? intermediateStock1 : intermediateStock3;
        BlockingQueue<Integer> targetStock = (workshopId == 3) ? intermediateStock3 : outputStock;

        int itemsToProcess = (workshopId == 3) ? 
            intermediateStock1.size() + intermediateStock2.size() : 
            intermediateStock3.size();

        int itemsProcessed = 0;

        while (itemsProcessed < itemsToProcess) {
            try {
                // Take item from source stock
                Integer item = sourceStock.take();

                // Process in workshop
                Thread.sleep(processingTime);

                // Move to target stock
                targetStock.offer(item);

                if (workshopId == 4) {
                    incrementProcessedItems();
                }

                itemsProcessed++;
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                incrementErrors();
                break;
            } catch (Exception e) {
                incrementErrors();
            }
        }
    }

    @Override
    public FactoryPerformance getPerformanceMetrics() {
        FactoryPerformance performance = new FactoryPerformance(4, 3);
        performance.setProcessedItems(getProcessedItemsCount());
        performance.setErrors(errors);
        performance.setInputStockLevel(getRemainingInputStock());
        performance.setOutputStockLevel(getOutputStockCount());
        performance.setIntermediateStockLevel(0, intermediateStock1.size());
        performance.setIntermediateStockLevel(1, intermediateStock2.size());
        performance.setIntermediateStockLevel(2, intermediateStock3.size());
        return performance;
    }
}
